317	static int routine_get_local_clock(struct routine_clock_s *clock)
318	{
319	  struct tm local_time;
320	  time_t wall_time;
321	
322	  if (clock == NULL)
323	    {
324	      return -EINVAL;
325	    }
326	
327	  wall_time = time(NULL);
328	  if (wall_time < 0 || localtime_r(&wall_time, &local_time) == NULL ||
329	      local_time.tm_year + 1900 < 2020)
330	    {
331	      memset(clock, 0, sizeof(*clock));
332	      return -ENODATA;
333	    }
334	
335	  clock->day = (local_time.tm_year + 1900) * 366 + local_time.tm_yday;
336	  clock->hour = local_time.tm_hour;
337	  clock->minute = local_time.tm_min;
338	  clock->valid = true;
339	  return OK;
340	}
