342	static void routine_dispatch_due(struct routine_app_s *app)
343	{
344	  struct routine_due_event_s event;
345	
346	  while (routine_model_take_due(&app->model, &event) == OK)
347	    {
348	      int ui_ret = routine_ui_enqueue_due(&event);
349	
350	      if (ui_ret < 0 && ui_ret != -EALREADY)
351	        {
352	          syslog(LOG_ERR,
353	                 "routine_mgr: due UI queue id=%u failed: %d\n",
354	                 event.schedule_id, ui_ret);
355	        }
356	
357	#ifdef CONFIG_ROUTINE_MANAGER_VOICE
358	      if (app->audio_started)
359	        {
360	          struct audio_service_reminder_s reminder;
361	          int audio_ret;
362	
363	          reminder.schedule_id = event.schedule_id;
364	          reminder.text_id = event.text_id;
365	          reminder.hour = event.hour;
366	          reminder.minute = event.minute;
367	          audio_ret = audio_service_enqueue_reminder(&app->audio, &reminder);
368	          if (audio_ret < 0 && audio_ret != -EALREADY)
369	            {
370	              syslog(LOG_ERR,
371	                     "routine_mgr: due audio queue id=%u failed: %d\n",
372	                     event.schedule_id, audio_ret);
373	            }
374	        }
375	#endif
376	    }
377	}
