236	static int routine_enqueue_due(struct routine_model_s *model,
237	                               struct routine_schedule_item_s *item)
238	{
239	  struct routine_due_event_s *event;
240	  uint8_t tail;
241	  uint8_t bit = 1u << item->id;
242	
243	  if ((model->due_queued_mask & bit) != 0 || item->notified ||
244	      item->completed || item->reminder_count >= ROUTINE_REMINDER_LIMIT)
245	    {
246	      return OK;
247	    }
248	
249	  if (model->due_count >= ROUTINE_DUE_QUEUE_MAX)
250	    {
251	      return -ENOSPC;
252	    }
253	
254	  tail = (model->due_head + model->due_count) % ROUTINE_DUE_QUEUE_MAX;
255	  event = &model->due_queue[tail];
256	  memset(event, 0, sizeof(*event));
257	  item->notified = true;
258	  item->reminder_count++;
259	  model->snapshot.schedule_due_sequence++;
260	  event->sequence = model->snapshot.schedule_due_sequence;
261	  event->due_day = item->due_day;
262	  event->schedule_id = item->id;
263	  event->text_id = item->text_id;
264	  event->hour = item->hour;
265	  event->minute = item->minute;
266	  event->reminder_count = item->reminder_count;
267	  model->due_count++;
268	  model->due_queued_mask |= bit;
269	  return OK;
270	}
