272	static void routine_detect_due(struct routine_model_s *model,
273	                               int64_t old_time, int64_t new_time)
274	{
275	  struct routine_snapshot_s *snapshot = &model->snapshot;
276	  uint8_t i;
277	
278	  if (new_time <= old_time)
279	    {
280	      return;
281	    }
282	
283	  for (i = 0; i < snapshot->schedule_count; i++)
284	    {
285	      int64_t due = routine_item_minutes(&snapshot->schedule[i]);
286	
287	      if (due > old_time && due <= new_time)
288	        {
289	          routine_enqueue_due(model, &snapshot->schedule[i]);
290	        }
291	    }
292	}
