294	static void routine_advance_history(struct routine_model_s *model,
295	                                    int64_t old_time, int64_t new_time)
296	{
297	  struct routine_snapshot_s *snapshot = &model->snapshot;
298	  int64_t old_hour = old_time / 60;
299	  int64_t new_hour = new_time / 60;
300	  int64_t hour;
301	  int32_t value;
302	
303	  if (new_hour <= old_hour)
304	    {
305	      return;
306	    }
307	
308	  if (new_hour - old_hour > ROUTINE_TREND_POINTS)
309	    {
310	      old_hour = new_hour - ROUTINE_TREND_POINTS;
311	      snapshot->temperature_history_count = 0;
312	    }
313	
314	  value = model->environment_attached &&
315	          (snapshot->live_mask & ENV_METRIC_TEMPERATURE) == 0 ?
316	          ROUTINE_HISTORY_INVALID : snapshot->temperature_x100;
317	  for (hour = old_hour + 1; hour <= new_hour; hour++)
318	    {
319	      routine_history_append(snapshot, value, hour % 24);
320	    }
321	}
