370	int routine_model_update_clock(struct routine_model_s *model,
371	                               const struct routine_clock_s *clock)
372	{
373	  struct routine_snapshot_s *snapshot;
374	  int64_t old_time;
375	  int64_t new_time;
376	  bool day_changed;
377	
378	  if (model == NULL || clock == NULL || !clock->valid ||
379	      clock->hour > 23 || clock->minute > 59)
380	    {
381	      return -EINVAL;
382	    }
383	
384	  snapshot = &model->snapshot;
385	  old_time = routine_clock_minutes(snapshot->day, snapshot->hour,
386	                                   snapshot->minute);
387	  new_time = routine_clock_minutes(clock->day, clock->hour, clock->minute);
388	  day_changed = clock->day != snapshot->day;
389	
390	  if (new_time > old_time)
391	    {
392	      if (!day_changed)
393	        {
394	          routine_detect_due(model, old_time, new_time);
395	        }
396	
397	      routine_advance_history(model, old_time, new_time);
398	    }
399	
400	  snapshot->day = clock->day;
401	  snapshot->hour = clock->hour;
402	  snapshot->minute = clock->minute;
403	  snapshot->clock_valid = true;
404	  if (day_changed && new_time > old_time)
405	    {
406	      routine_reset_schedule(snapshot, clock->day, true);
407	      routine_detect_due(model,
408	                         routine_clock_minutes(clock->day, 0, 0) - 1,
409	                         new_time);
410	    }
411	
412	  routine_update_demo_values(model);
413	  return OK;
414	}
