416	void routine_model_tick_demo(struct routine_model_s *model)
417	{
418	  struct routine_clock_s clock;
419	  uint32_t total_minutes;
420	
421	  if (model == NULL || model->clock_mode != ROUTINE_CLOCK_DEMO)
422	    {
423	      return;
424	    }
425	
426	  model->elapsed_seconds++;
427	  total_minutes = (8 * 60) +
428	                  (model->elapsed_seconds * 60 / model->seconds_per_hour);
429	  clock.day = total_minutes / (24 * 60);
430	  clock.hour = total_minutes / 60 % 24;
431	  clock.minute = total_minutes % 60;
432	  clock.valid = true;
433	  routine_model_update_clock(model, &clock);
434	}
