500	static void routine_restore_after_carry_over(struct routine_model_s *model,
501	                                             uint8_t index)
502	{
503	  struct routine_snapshot_s *snapshot = &model->snapshot;
504	  uint8_t id = snapshot->schedule[index].id;
505	  int64_t now = routine_clock_minutes(snapshot->day, snapshot->hour,
506	                                      snapshot->minute);
507	  struct routine_schedule_item_s item;
508	
509	  routine_set_default_item(&item, id, snapshot->day);
510	  if (routine_item_minutes(&item) < now)
511	    {
512	      item.completed = true;
513	    }
514	
515	  snapshot->schedule[index] = item;
516	}
517	
518	int routine_model_schedule_action_id(struct routine_model_s *model,
519	                                     uint8_t schedule_id,
520	                                     enum routine_schedule_action_e action)
521	{
522	  struct routine_snapshot_s *snapshot;
523	  struct routine_schedule_item_s *item;
524	  int64_t minutes;
525	  int64_t now;
526	  int index;
527	
528	  if (model == NULL || schedule_id >= ROUTINE_SCHEDULE_MAX)
529	    {
530	      return -EINVAL;
531	    }
532	
533	  snapshot = &model->snapshot;
534	  index = routine_find_schedule_id(snapshot, schedule_id);
535	  if (index < 0)
536	    {
537	      return index;
538	    }
539	
540	  item = &snapshot->schedule[index];
541	  switch (action)
542	    {
543	      case ROUTINE_SCHEDULE_COMPLETE:
544	        if (item->carry_over)
545	          {
546	            routine_restore_after_carry_over(model, index);
547	          }
548	        else
549	          {
550	            item->completed = true;
551	          }
552	        break;
553	
554	      case ROUTINE_SCHEDULE_DELAY_10_MINUTES:
555	        if (item->completed)
556	          {
557	            return -EALREADY;
558	          }
559	
560	        now = routine_clock_minutes(snapshot->day, snapshot->hour,
561	                                    snapshot->minute);
562	        minutes = routine_item_minutes(item);
563	        if (minutes < now)
564	          {
565	            minutes = now;
566	          }
567	
568	        minutes += 10;
569	        item->due_day = minutes / (24 * 60);
570	        item->hour = minutes / 60 % 24;
571	        item->minute = minutes % 60;
572	        item->reminder_count = 0;
573	        item->notified = false;
574	        item->carry_over = item->carry_over ||
575	                           item->due_day > snapshot->day;
576	        break;
577	
578	      case ROUTINE_SCHEDULE_DISMISS:
579	        if (item->completed || !item->notified)
580	          {
581	            return -EALREADY;
582	          }
583	
584	        if (item->reminder_count < ROUTINE_REMINDER_LIMIT)
585	          {
586	            minutes = routine_clock_minutes(snapshot->day, snapshot->hour,
587	                                            snapshot->minute) + 10;
588	            item->due_day = minutes / (24 * 60);
589	            item->hour = minutes / 60 % 24;
590	            item->minute = minutes % 60;
591	            item->notified = false;
592	            item->carry_over = item->carry_over ||
593	                               item->due_day > snapshot->day;
594	          }
595	        break;
596	
597	      default:
598	        return -EINVAL;
599	    }
600	
601	  routine_sort_schedule(snapshot);
602	  snapshot->next_schedule = routine_find_next_schedule(snapshot);
603	  return OK;
604	}
