786	  snapshot = routine_model_get_snapshot(&model);
787	  if (snapshot->temperature_history_count != 1 ||
788	      snapshot->temperature_history[0] != 2345 ||
789	      routine_selftest_set_clock(&model, 30, 13, 0) < 0 ||
790	      snapshot->temperature_history_count != 2)
791	    {
792	      return -EINVAL;
793	    }
794	
795	  environment.live_mask = 0;
796	  environment.offline_mask = ENV_METRIC_TEMPERATURE |
797	                             ENV_METRIC_HUMIDITY;
798	  routine_model_apply_environment(&model, &environment);
799	  if (snapshot->temperature_history[1] != ROUTINE_HISTORY_INVALID ||
800	      snapshot->humidity_x100 > 10000 || snapshot->hour > 23 ||
801	      snapshot->minute > 59)
802	    {
