144	static int audio_service_play(FAR struct audio_service_s *service,
145	                              uint32_t generation,
146	                              uint32_t duration_ms)
147	{
148	  struct timespec delay;
149	  uint16_t nxplayer_volume;
150	  uint32_t elapsed;
151	  bool cancelled;
152	  bool timed_out;
153	  int ret;
154	
155	  service->player = nxplayer_create();
156	  if (service->player == NULL)
157	    {
158	      return -ENOMEM;
159	    }
160	
161	  ret = nxplayer_setdevice(service->player,
162	                           service->config.playback_device);
163	  if (ret < 0)
164	    {
165	      nxplayer_release(service->player);
166	      service->player = NULL;
167	      return ret;
168	    }
169	
170	#ifndef CONFIG_AUDIO_EXCLUDE_VOLUME
171	  nxplayer_volume = audio_service_nxplayer_volume(service->config.volume);
172	  syslog(LOG_INFO,
173	         "routine_mgr: playback volume=%u%% nxplayer_volume=%u\n",
174	         service->config.volume, nxplayer_volume);
175	  ret = nxplayer_setvolume(service->player, nxplayer_volume);
176	  if (ret < 0)
177	    {
178	      nxplayer_release(service->player);
179	      service->player = NULL;
180	      return ret;
181	    }
182	#endif
183	
184	  ret = nxplayer_playraw(service->player, service->config.reply_path,
185	                         AUDIO_FMT_PCM, AUDIO_FMT_UNDEF,
186	                         AUDIO_SERVICE_PLAY_CHANNELS,
187	                         AUDIO_SERVICE_BITS_PER_SAMPLE,
188	                         AUDIO_SERVICE_SAMPLE_RATE,
189	                         AUDIO_SERVICE_PLAY_CHMAP);
190	  if (ret < 0)
191	    {
192	      nxplayer_release(service->player);
193	      service->player = NULL;
194	      return ret;
195	    }
196	
197	  delay.tv_sec = 0;
198	  delay.tv_nsec = AUDIO_SERVICE_POLL_MS * 1000000;
199	  cancelled = false;
200	  timed_out = true;
201	  for (elapsed = 0; elapsed <= duration_ms + 1000;
202	       elapsed += AUDIO_SERVICE_POLL_MS)
203	    {
204	      cancelled = audio_service_cancelled(service, generation);
205	      if (cancelled || service->player->state == AUDIO_SERVICE_PLAYER_IDLE)
206	        {
207	          timed_out = false;
208	          break;
209	        }
210	
211	      nanosleep(&delay, NULL);
212	    }
213	
214	  if (service->player->state != AUDIO_SERVICE_PLAYER_IDLE)
215	    {
216	      syslog(LOG_INFO, "routine_mgr: stopping playback (%s)\n",
217	             cancelled ? "cancelled" : "timeout");
218	      ret = nxplayer_stop(service->player);
219	      if (ret < 0)
220	        {
221	          nxplayer_release(service->player);
222	          service->player = NULL;
223	          return ret;
224	        }
225	    }
226	
227	  nxplayer_release(service->player);
228	  service->player = NULL;
229	  return timed_out ? -ETIMEDOUT : OK;
230	}
