295	static void audio_service_process(FAR struct audio_service_s *service,
296	                                  uint32_t generation)
297	{
298	  struct voice_recognition_result_s recognition;
299	  struct voice_reply_values_s values;
300	  enum audio_service_request_e request;
301	  enum voice_reply_type_e reply_type;
302	  uint32_t duration_ms;
303	  uint32_t required;
304	  int ret;
305	
306	  pthread_mutex_lock(&service->lock);
307	  request = service->request;
308	  values = service->sensor.values;
309	  if (request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER)
310	    {
311	      values.schedule_text_id = service->current_reminder.text_id;
312	      values.schedule_hour = service->current_reminder.hour;
313	      values.schedule_minute = service->current_reminder.minute;
314	    }
315	
316	  pthread_mutex_unlock(&service->lock);
317	
318	  if (request != AUDIO_SERVICE_REQUEST_QUERY)
319	    {
320	      if (request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER)
321	        {
322	          required = 0;
323	          reply_type = VOICE_REPLY_SCHEDULE_REMINDER;
324	          ret = OK;
325	        }
326	      else
327	        {
328	          ret = audio_service_sensor_request_spec(request, &required,
329	                                                  &reply_type);
330	        }
331	
332	      if (ret < 0)
333	        {
334	          audio_service_publish(service, AUDIO_SERVICE_ERROR,
335	                                AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
336	          return;
337	        }
338	
339	      audio_service_publish(service, AUDIO_SERVICE_PROCESSING,
340	                            AUDIO_SERVICE_ERROR_NONE);
341	      ret = voice_reply_build(service->config.asset_dir,
342	                              service->config.reply_path,
343	                              reply_type, &values, &duration_ms);
344	      if (ret < 0)
345	        {
346	          syslog(LOG_ERR,
347	                 "routine_mgr: sensor reply request=%u build failed: %d\n",
348	                 request, ret);
349	          audio_service_publish(service, AUDIO_SERVICE_ERROR,
350	                                AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
351	          return;
352	        }
353	
354	      audio_service_publish(service, AUDIO_SERVICE_SPEAKING,
355	                            AUDIO_SERVICE_ERROR_NONE);
356	      ret = audio_service_play(service, generation, duration_ms);
357	      unlink(service->config.reply_path);
358	      if (audio_service_cancelled(service, generation))
359	        {
360	          audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
361	          return;
362	        }
363	
364	      if (ret < 0)
365	        {
366	          audio_service_publish(service, AUDIO_SERVICE_ERROR,
367	                                AUDIO_SERVICE_ERROR_PLAYBACK);
368	          return;
369	        }
370	
371	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_COMPLETED);
372	      return;
373	    }
374	
375	  audio_service_publish(service, AUDIO_SERVICE_LISTENING,
376	                        AUDIO_SERVICE_ERROR_NONE);
377	  ret = audio_service_capture(service, generation);
378	  if (audio_service_cancelled(service, generation))
379	    {
380	      unlink(service->config.record_path);
381	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
382	      return;
383	    }
384	
385	  if (ret < 0)
386	    {
387	      audio_service_publish(service, AUDIO_SERVICE_ERROR,
388	                            AUDIO_SERVICE_ERROR_CAPTURE);
389	      return;
390	    }
391	
392	  audio_service_publish(service, AUDIO_SERVICE_PROCESSING,
393	                        AUDIO_SERVICE_ERROR_NONE);
394	  ret = voice_recognizer_demo_recognize(service->config.record_path,
395	                                        &recognition);
396	  unlink(service->config.record_path);
397	  if (audio_service_cancelled(service, generation))
398	    {
399	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
400	      return;
401	    }
402	
403	  if (ret < 0 || recognition.command != VOICE_COMMAND_QUERY_TEMPERATURE)
404	    {
405	      audio_service_publish(service, AUDIO_SERVICE_ERROR,
406	                            AUDIO_SERVICE_ERROR_NO_VOICE);
407	      return;
408	    }
409	
410	  pthread_mutex_lock(&service->lock);
411	  values = service->sensor.values;
412	  service->recognition_score = recognition.score;
413	  service->semantic_verified = recognition.semantic_verified;
414	  service->has_result = true;
415	  service->sequence++;
416	  pthread_mutex_unlock(&service->lock);
417	
418	  ret = voice_reply_build(service->config.asset_dir,
419	                          service->config.reply_path,
420	                          VOICE_REPLY_TEMPERATURE, &values, &duration_ms);
421	  if (ret < 0)
422	    {
423	      syslog(LOG_ERR, "routine_mgr: failed to build voice reply: %d\n", ret);
424	      audio_service_publish(service, AUDIO_SERVICE_ERROR,
425	                            AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
426	      return;
427	    }
428	
429	  audio_service_publish(service, AUDIO_SERVICE_SPEAKING,
430	                        AUDIO_SERVICE_ERROR_NONE);
431	  ret = audio_service_play(service, generation, duration_ms);
432	  unlink(service->config.reply_path);
433	  if (audio_service_cancelled(service, generation))
434	    {
435	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
436	      return;
437	    }
438	
439	  if (ret < 0)
440	    {
441	      audio_service_publish(service, AUDIO_SERVICE_ERROR,
442	                            AUDIO_SERVICE_ERROR_PLAYBACK);
443	      return;
444	    }
445	
446	  audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_COMPLETED);
447	}
