449	static FAR void *audio_service_thread(FAR void *arg)
450	{
451	  FAR struct audio_service_s *service = arg;
452	
453	  while (true)
454	    {
455	      uint32_t generation;
456	
457	      pthread_mutex_lock(&service->lock);
458	      while (!service->start_requested && service->reminder_count == 0 &&
459	             !service->shutdown_requested)
460	        {
461	          pthread_cond_wait(&service->cond, &service->lock);
462	        }
463	
464	      if (service->shutdown_requested)
465	        {
466	          pthread_mutex_unlock(&service->lock);
467	          break;
468	        }
469	
470	      if (!service->start_requested && service->reminder_count > 0)
471	        {
472	          service->current_reminder =
473	            service->reminder_queue[service->reminder_head];
474	          service->reminder_head =
475	            (service->reminder_head + 1) % AUDIO_SERVICE_REMINDER_MAX;
476	          service->reminder_count--;
477	          service->reminder_queued_mask &=
478	            ~(1u << service->current_reminder.schedule_id);
479	          service->generation++;
480	          service->request = AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER;
481	          service->state = AUDIO_SERVICE_PROCESSING;
482	          service->error = AUDIO_SERVICE_ERROR_NONE;
483	          service->outcome = AUDIO_SERVICE_OUTCOME_NONE;
484	          service->sequence++;
485	        }
486	
487	      service->start_requested = false;
488	      service->cancel_requested = false;
489	      generation = service->generation;
490	      pthread_mutex_unlock(&service->lock);
491	      audio_service_process(service, generation);
492	    }
493	
494	  return NULL;
495	}
