497	int audio_service_initialize(FAR struct audio_service_s *service,
498	                             FAR const struct audio_service_config_s *config)
499	{
500	  struct sched_param sched;
501	  pthread_attr_t attr;
502	  int ret;
503	
504	  if (service == NULL || config == NULL || config->capture_device == NULL ||
505	      config->playback_device == NULL || config->record_path == NULL ||
506	      config->reply_path == NULL || config->asset_dir == NULL ||
507	      config->record_ms == 0 || config->volume < 1 || config->volume > 100)
508	    {
509	      return -EINVAL;
510	    }
511	
512	  memset(service, 0, sizeof(*service));
513	  service->config = *config;
514	  service->state = AUDIO_SERVICE_IDLE;
515	  ret = pthread_mutex_init(&service->lock, NULL);
516	  if (ret != 0)
517	    {
518	      return -ret;
519	    }
520	
521	  ret = pthread_cond_init(&service->cond, NULL);
522	  if (ret != 0)
523	    {
524	      pthread_mutex_destroy(&service->lock);
525	      return -ret;
526	    }
527	
528	  pthread_attr_init(&attr);
529	  if (config->stack_size > 0)
530	    {
531	      pthread_attr_setstacksize(&attr, config->stack_size);
532	    }
533	
534	  if (config->priority > 0)
535	    {
536	      memset(&sched, 0, sizeof(sched));
537	      sched.sched_priority = config->priority;
538	      pthread_attr_setschedparam(&attr, &sched);
539	    }
540	
541	  ret = pthread_create(&service->thread, &attr, audio_service_thread, service);
542	  pthread_attr_destroy(&attr);
543	  if (ret != 0)
544	    {
545	      pthread_cond_destroy(&service->cond);
546	      pthread_mutex_destroy(&service->lock);
547	      return -ret;
548	    }
549	
550	  service->thread_created = true;
551	  service->initialized = true;
552	  return OK;
553	}
