587	                              enum audio_service_request_e request)
588	{
589	  uint32_t required;
590	
591	  if (service == NULL || !service->initialized ||
592	      audio_service_sensor_request_spec(request, &required, NULL) < 0)
593	    {
594	      return -EINVAL;
595	    }
596	
597	  pthread_mutex_lock(&service->lock);
598	  if (service->state != AUDIO_SERVICE_IDLE &&
599	      service->state != AUDIO_SERVICE_ERROR)
600	    {
601	      pthread_mutex_unlock(&service->lock);
602	      return -EBUSY;
603	    }
