614	      return -ENODATA;
615	    }
616	
617	  service->generation++;
618	  service->request = request;
619	  service->start_requested = true;
620	  service->cancel_requested = false;
621	  service->state = AUDIO_SERVICE_PROCESSING;
622	  service->error = AUDIO_SERVICE_ERROR_NONE;
623	  service->outcome = AUDIO_SERVICE_OUTCOME_NONE;
624	  service->has_result = false;
625	  service->sequence++;
