631	int audio_service_enqueue_reminder(
632	  FAR struct audio_service_s *service,
633	  FAR const struct audio_service_reminder_s *reminder)
634	{
635	  uint8_t bit;
636	  uint8_t tail;
637	
638	  if (service == NULL || reminder == NULL || !service->initialized ||
639	      reminder->schedule_id >= AUDIO_SERVICE_REMINDER_MAX ||
640	      reminder->text_id >= AUDIO_SERVICE_REMINDER_MAX ||
641	      reminder->hour > 23 || reminder->minute > 59)
642	    {
643	      return -EINVAL;
644	    }
645	
646	  bit = 1u << reminder->schedule_id;
647	  pthread_mutex_lock(&service->lock);
648	  if ((service->reminder_queued_mask & bit) != 0 ||
649	      (service->request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER &&
650	       service->current_reminder.schedule_id == reminder->schedule_id &&
651	       service->state != AUDIO_SERVICE_IDLE &&
652	       service->state != AUDIO_SERVICE_ERROR))
653	    {
654	      pthread_mutex_unlock(&service->lock);
655	      return -EALREADY;
656	    }
657	
658	  if (service->reminder_count >= AUDIO_SERVICE_REMINDER_MAX)
659	    {
660	      pthread_mutex_unlock(&service->lock);
661	      return -ENOSPC;
662	    }
663	
664	  tail = (service->reminder_head + service->reminder_count) %
665	         AUDIO_SERVICE_REMINDER_MAX;
666	  service->reminder_queue[tail] = *reminder;
667	  service->reminder_count++;
668	  service->reminder_queued_mask |= bit;
669	  pthread_cond_signal(&service->cond);
670	  pthread_mutex_unlock(&service->lock);
671	  return OK;
672	}
