587	static void routine_try_open_due(void)
588	{
589	  struct routine_due_event_s event;
590	
591	  if (g_ui.dialog != NULL || g_ui.due_count == 0)
592	    {
593	      return;
594	    }
595	
596	  event = g_ui.due_queue[g_ui.due_head];
597	  g_ui.due_head = (g_ui.due_head + 1) % ROUTINE_DUE_UI_QUEUE_MAX;
598	  g_ui.due_count--;
599	  g_ui.due_queued_mask &= ~(1u << event.schedule_id);
600	  routine_open_due_dialog(&event);
601	}
602	
603	int routine_ui_enqueue_due(const struct routine_due_event_s *event)
604	{
605	  uint8_t tail;
606	  uint8_t bit;
607	
608	  if (event == NULL || event->schedule_id >= ROUTINE_SCHEDULE_MAX)
609	    {
610	      return -EINVAL;
611	    }
612	
613	  bit = 1u << event->schedule_id;
614	  if ((g_ui.due_queued_mask & bit) != 0 ||
615	      (g_ui.dialog_is_due && g_ui.selected_schedule == event->schedule_id))
616	    {
617	      return -EALREADY;
618	    }
619	
620	  if (g_ui.due_count >= ROUTINE_DUE_UI_QUEUE_MAX)
621	    {
622	      return -ENOSPC;
623	    }
624	
625	  tail = (g_ui.due_head + g_ui.due_count) % ROUTINE_DUE_UI_QUEUE_MAX;
626	  g_ui.due_queue[tail] = *event;
627	  g_ui.due_count++;
628	  g_ui.due_queued_mask |= bit;
629	  routine_try_open_due();
630	  return OK;
631	}
