633	static void routine_format_sensor_details(enum routine_ui_dialog_e type)
634	{
635	  const struct routine_snapshot_s *snapshot = &g_ui.snapshot;
636	  uint32_t mask = routine_dialog_mask(type);
637	  enum routine_sensor_state_e status = routine_metric_status(snapshot, mask);
638	  char temperature[24];
639	
640	  routine_format_signed_x100(temperature, sizeof(temperature),
641	                             snapshot->temperature_x100, " C");
642	  if (type == ROUTINE_UI_DIALOG_TEMPERATURE)
643	    {
644	      snprintf(g_ui.dialog_buffer, sizeof(g_ui.dialog_buffer),
645	               "SHT40  %s\n%s  %s\n%s",
646	               g_ui.text->status[status], g_ui.text->detail_temperature,
647	               temperature, g_ui.text->status_help[status]);
648	    }
649	  else if (type == ROUTINE_UI_DIALOG_HUMIDITY)
650	    {
651	      snprintf(g_ui.dialog_buffer, sizeof(g_ui.dialog_buffer),
652	               "SHT40  %s\n%s  %u.%02u%%\n%s",
653	               g_ui.text->status[status], g_ui.text->detail_humidity,
654	               snapshot->humidity_x100 / 100,
655	               snapshot->humidity_x100 % 100,
656	               g_ui.text->status_help[status]);
657	    }
658	  else if (type == ROUTINE_UI_DIALOG_BH1750)
659	    {
660	      snprintf(g_ui.dialog_buffer, sizeof(g_ui.dialog_buffer),
661	               "BH1750  %s\n%s  %lu.%lu lux\n%s",
662	               g_ui.text->status[status], g_ui.text->detail_light,
663	               (unsigned long)(snapshot->light_x10 / 10),
664	               (unsigned long)(snapshot->light_x10 % 10),
665	               g_ui.text->status_help[status]);
666	    }
667	  else
668	    {
669	      snprintf(g_ui.dialog_buffer, sizeof(g_ui.dialog_buffer),
670	               "SGP30  %s\neCO2  %u ppm\nTVOC  %u ppb\n%s",
671	               g_ui.text->status[status], snapshot->eco2_ppm,
672	               snapshot->tvoc_ppb, g_ui.text->status_help[status]);
673	    }
674	}
