676	static void routine_sync_dialog_play_state(void)
677	{
678	  enum audio_service_request_e request;
679	  enum routine_sensor_state_e status;
680	  bool owns_active;
681	
682	  if (g_ui.dialog_play_button == NULL ||
683	      !routine_dialog_is_sensor(g_ui.dialog_type))
684	    {
685	      return;
686	    }
687	
688	  request = routine_dialog_request(g_ui.dialog_type);
689	  owns_active = g_ui.voice_active && g_ui.active_request == request;
690	  status = routine_metric_status(&g_ui.snapshot,
691	                                 routine_dialog_mask(g_ui.dialog_type));
692	  if (owns_active || status == ROUTINE_SENSOR_LIVE)
693	    {
694	      lv_obj_clear_state(g_ui.dialog_play_button, LV_STATE_DISABLED);
695	    }
696	  else
697	    {
698	      lv_obj_add_state(g_ui.dialog_play_button, LV_STATE_DISABLED);
699	      if (g_ui.dialog_play_status != NULL)
700	        {
701	          lv_label_set_text_static(
702	            g_ui.dialog_play_status,
703	            status == ROUTINE_SENSOR_OFFLINE ?
704	            g_ui.text->voice_errors[AUDIO_SERVICE_ERROR_SENSOR_UNAVAILABLE] :
705	            g_ui.text->status_help[status]);
706	        }
707	    }
708	}
