1199	static void routine_chart_visible_range(int32_t *minimum, int32_t *maximum)
1200	{
1201	  int32_t low = 0;
1202	  int32_t high = 0;
1203	  bool found = false;
1204	  uint8_t i;
1205	
1206	  for (i = 0; i < ROUTINE_CHART_POINTS; i++)
1207	    {
1208	      uint8_t id = g_ui.history_start + i;
1209	      int32_t value;
1210	
1211	      if (id >= g_ui.snapshot.temperature_history_count)
1212	        {
1213	          continue;
1214	        }
1215	
1216	      value = g_ui.snapshot.temperature_history[id];
1217	      if (value == ROUTINE_HISTORY_INVALID)
1218	        {
1219	          continue;
1220	        }
1221	
1222	      if (!found || value < low)
1223	        {
1224	          low = value;
1225	        }
1226	
1227	      if (!found || value > high)
1228	        {
1229	          high = value;
1230	        }
1231	
1232	      found = true;
1233	    }
1234	
1235	  if (!found)
1236	    {
1237	      *minimum = 1800;
1238	      *maximum = 3000;
1239	      return;
1240	    }
1241	
1242	  if (high - low < 200)
1243	    {
1244	      int32_t center = low + (high - low) / 2;
1245	      low = center - 100;
1246	      high = center + 100;
1247	    }
1248	  else
1249	    {
1250	      int32_t padding = (high - low) / 10;
1251	      padding = padding < 100 ? 100 : padding;
1252	      low -= padding;
1253	      high += padding;
1254	    }
1255	
1256	  *minimum = low < -4500 ? -4500 : low;
1257	  *maximum = high > 13000 ? 13000 : high;
1258	  if (*minimum >= *maximum)
1259	    {
1260	      *minimum = *maximum - 100;
1261	    }
1262	}
