1264	void routine_ui_update(const struct routine_snapshot_s *snapshot)
1265	{
1266	  static const uint32_t mask[ROUTINE_SENSOR_CARD_COUNT] =
1267	  {
1268	    ENV_METRIC_TEMPERATURE,
1269	    ENV_METRIC_HUMIDITY,
1270	    ENV_METRIC_LIGHT,
1271	    ENV_METRIC_ECO2 | ENV_METRIC_TVOC
1272	  };
1273	  enum routine_sensor_state_e status;
1274	  uint8_t count;
1275	  uint8_t latest;
1276	  uint8_t i;
1277	
1278	  if (g_ui.root == NULL || snapshot == NULL)
1279	    {
1280	      return;
1281	    }
1282	
1283	  g_ui.snapshot = *snapshot;
1284	  snprintf(g_ui.time_buffer, sizeof(g_ui.time_buffer), "%02u:%02u",
1285	           snapshot->hour, snapshot->minute);
1286	  lv_label_set_text_static(g_ui.time_label, g_ui.time_buffer);
1287	
1288	  routine_format_signed_x100(g_ui.value_buffer[0],
1289	                             sizeof(g_ui.value_buffer[0]),
1290	                             snapshot->temperature_x100, " C");
1291	  snprintf(g_ui.value_buffer[1], sizeof(g_ui.value_buffer[1]), "%u.%02u%%",
1292	           snapshot->humidity_x100 / 100, snapshot->humidity_x100 % 100);
1293	  snprintf(g_ui.value_buffer[2], sizeof(g_ui.value_buffer[2]), "%lu.%lu lux",
1294	           (unsigned long)(snapshot->light_x10 / 10),
1295	           (unsigned long)(snapshot->light_x10 % 10));
1296	  snprintf(g_ui.value_buffer[3], sizeof(g_ui.value_buffer[3]), "eCO2 %u ppm",
1297	           snapshot->eco2_ppm);
1298	  snprintf(g_ui.subvalue_buffer[0], sizeof(g_ui.subvalue_buffer[0]), "SHT40");
1299	  snprintf(g_ui.subvalue_buffer[1], sizeof(g_ui.subvalue_buffer[1]), "SHT40");
1300	  snprintf(g_ui.subvalue_buffer[2], sizeof(g_ui.subvalue_buffer[2]), "BH1750");
1301	  snprintf(g_ui.subvalue_buffer[3], sizeof(g_ui.subvalue_buffer[3]),
1302	           "TVOC %u ppb", snapshot->tvoc_ppb);
1303	
1304	  for (i = 0; i < ROUTINE_SENSOR_CARD_COUNT; i++)
1305	    {
1306	      status = routine_metric_status(snapshot, mask[i]);
1307	      if (status == ROUTINE_SENSOR_OFFLINE ||
1308	          status == ROUTINE_SENSOR_STALE ||
1309	          (status == ROUTINE_SENSOR_WARMUP && i == 3))
1310	        {
1311	          snprintf(g_ui.value_buffer[i], sizeof(g_ui.value_buffer[i]), "--");
1312	          if (i == 3)
1313	            {
1314	              snprintf(g_ui.subvalue_buffer[i],
1315	                       sizeof(g_ui.subvalue_buffer[i]), "SGP30");
1316	            }
1317	        }
1318	
1319	      lv_label_set_text_static(g_ui.value_labels[i], g_ui.value_buffer[i]);
1320	      lv_label_set_text_static(g_ui.subvalue_labels[i],
1321	                               g_ui.subvalue_buffer[i]);
1322	      lv_label_set_text_static(g_ui.card_status[i], g_ui.text->status[status]);
1323	      lv_obj_set_style_text_color(g_ui.card_status[i],
1324	                                  routine_status_color(status), 0);
1325	    }
1326	
1327	  count = snapshot->temperature_history_count;
1328	  latest = count > ROUTINE_CHART_POINTS ? count - ROUTINE_CHART_POINTS : 0;
1329	  if (g_ui.history_start > latest)
1330	    {
1331	      g_ui.history_start = latest;
1332	    }
1333	  else if (g_ui.history_follow_latest)
1334	    {
1335	      g_ui.history_start = latest;
1336	    }
1337	
1338	  for (i = 0; i < ROUTINE_CHART_POINTS; i++)
1339	    {
1340	      uint8_t id = g_ui.history_start + i;
1341	      int32_t value = id < count ? snapshot->temperature_history[id] :
1342	                                   ROUTINE_HISTORY_INVALID;
1343	      lv_chart_set_value_by_id(g_ui.chart, g_ui.temperature_series, i,
1344	                               value == ROUTINE_HISTORY_INVALID ?
1345	                               LV_CHART_POINT_NONE : value);
1346	      if (id < count)
1347	        {
1348	          snprintf(g_ui.chart_axis_buffer[i],
1349	                   sizeof(g_ui.chart_axis_buffer[i]), "%02u",
1350	                   snapshot->temperature_history_hour[id]);
1351	        }
1352	      else
1353	        {
1354	          snprintf(g_ui.chart_axis_buffer[i],
1355	                   sizeof(g_ui.chart_axis_buffer[i]), "--");
1356	        }
1357	      lv_label_set_text_static(g_ui.chart_axis[i], g_ui.chart_axis_buffer[i]);
1358	    }
1359	
1360	  {
1361	    int32_t chart_min;
1362	    int32_t chart_max;
1363	
1364	    routine_chart_visible_range(&chart_min, &chart_max);
1365	    if (chart_min != g_ui.chart_min || chart_max != g_ui.chart_max)
1366	      {
1367	        g_ui.chart_min = chart_min;
1368	        g_ui.chart_max = chart_max;
1369	        lv_chart_set_range(g_ui.chart, LV_CHART_AXIS_PRIMARY_Y,
1370	                           chart_min, chart_max);
1371	      }
1372	  }
1373	
1374	  if (count > 0)
1375	    {
1376	      uint8_t end = g_ui.history_start + ROUTINE_CHART_POINTS;
1377	      if (end > count)
1378	        {
1379	          end = count;
1380	        }
1381	      snprintf(g_ui.chart_range_buffer, sizeof(g_ui.chart_range_buffer),
1382	               "%u-%u / %u", g_ui.history_start + 1, end, count);
1383	    }
1384	  else
1385	    {
1386	      snprintf(g_ui.chart_range_buffer, sizeof(g_ui.chart_range_buffer),
1387	               "0 / 0");
1388	    }
1389	  lv_label_set_text_static(g_ui.chart_range, g_ui.chart_range_buffer);
1390	  if (g_ui.history_start == 0)
1391	    {
1392	      lv_obj_add_state(g_ui.chart_prev, LV_STATE_DISABLED);
1393	    }
1394	  else
1395	    {
1396	      lv_obj_clear_state(g_ui.chart_prev, LV_STATE_DISABLED);
1397	    }
1398	  if (g_ui.history_start >= latest)
1399	    {
1400	      lv_obj_add_state(g_ui.chart_next, LV_STATE_DISABLED);
1401	    }
1402	  else
1403	    {
1404	      lv_obj_clear_state(g_ui.chart_next, LV_STATE_DISABLED);
1405	    }
1406	
1407	  for (i = 0; i < ROUTINE_SCHEDULE_MAX; i++)
1408	    {
1409	      snprintf(g_ui.schedule_time_buffer[i],
1410	               sizeof(g_ui.schedule_time_buffer[i]), "%02u:%02u",
1411	               snapshot->schedule[i].hour, snapshot->schedule[i].minute);
1412	      lv_label_set_text_static(g_ui.schedule_time[i],
1413	                               g_ui.schedule_time_buffer[i]);
1414	      lv_label_set_text_static(g_ui.schedule_text[i],
1415	                               routine_schedule_text(
1416	                                 snapshot->schedule[i].text_id));
1417	      if (snapshot->schedule[i].completed)
1418	        {
1419	          lv_obj_set_style_bg_color(g_ui.schedule_bars[i],
1420	                                    ROUTINE_COLOR_GREEN, 0);
1421	          lv_label_set_text_static(g_ui.schedule_next[i],
1422	                                   g_ui.text->completed);
1423	        }
1424	      else if (snapshot->next_schedule == i)
1425	        {
1426	          lv_obj_set_style_bg_color(g_ui.schedule_bars[i],
1427	                                    ROUTINE_COLOR_ORANGE, 0);
1428	          lv_label_set_text_static(g_ui.schedule_next[i], g_ui.text->next);
1429	        }
1430	      else
1431	        {
1432	          lv_obj_set_style_bg_color(g_ui.schedule_bars[i],
1433	                                    ROUTINE_COLOR_GRID, 0);
1434	          lv_label_set_text_static(g_ui.schedule_next[i], "");
1435	        }
1436	    }
1437	
1438	  if (g_ui.dialog_text != NULL &&
1439	      routine_dialog_is_sensor(g_ui.dialog_type))
1440	    {
1441	      routine_format_sensor_details(g_ui.dialog_type);
1442	      lv_label_set_text_static(g_ui.dialog_text, g_ui.dialog_buffer);
1443	      routine_sync_dialog_play_state();
1444	    }
1445	}
