1447	void routine_ui_voice_update(
1448	  const struct audio_service_snapshot_s *snapshot)
1449	{
1450	  const char *status;
1451	  bool active;
1452	
1453	  if (snapshot == NULL || g_ui.voice_status == NULL ||
1454	      snapshot->sequence == g_ui.last_audio_sequence)
1455	    {
1456	      return;
1457	    }
1458	
1459	  g_ui.last_audio_sequence = snapshot->sequence;
1460	  active = snapshot->state == AUDIO_SERVICE_LISTENING ||
1461	           snapshot->state == AUDIO_SERVICE_PROCESSING ||
1462	           snapshot->state == AUDIO_SERVICE_SPEAKING;
1463	  if (snapshot->state == AUDIO_SERVICE_LISTENING)
1464	    {
1465	      status = g_ui.text->voice_listening;
1466	    }
1467	  else if (snapshot->state == AUDIO_SERVICE_PROCESSING)
1468	    {
1469	      status = g_ui.text->voice_processing;
1470	    }
1471	  else if (snapshot->state == AUDIO_SERVICE_SPEAKING)
1472	    {
1473	      status = g_ui.text->voice_speaking;
