1475	  else if (snapshot->state == AUDIO_SERVICE_ERROR &&
1476	           snapshot->error <= AUDIO_SERVICE_ERROR_SENSOR_UNAVAILABLE)
1477	    {
1478	      status = g_ui.text->voice_errors[snapshot->error];
1479	    }

