293	static void routine_format_signed_x100(FAR char *buffer, size_t size,
294	                                       int32_t value, FAR const char *unit)
295	{
296	  int32_t whole = value / 100;
297	  int32_t fraction = abs(value % 100);
298	
299	  if (value < 0 && whole == 0)
300	    {
301	      snprintf(buffer, size, "-0.%02ld%s", (long)fraction, unit);
302	    }
303	  else
304	    {
305	      snprintf(buffer, size, "%ld.%02ld%s", (long)whole,
306	               (long)fraction, unit);
307	    }
308	}
