948	static void routine_history_button_cb(lv_event_t *event)
949	{
950	  int direction = (int)(intptr_t)lv_event_get_user_data(event);
951	  uint8_t count = g_ui.snapshot.temperature_history_count;
952	  uint8_t latest = count > ROUTINE_CHART_POINTS ?
953	                   count - ROUTINE_CHART_POINTS : 0;
954	
955	  if (direction < 0)
956	    {
957	      g_ui.history_start = g_ui.history_start >= ROUTINE_CHART_POINTS ?
958	                           g_ui.history_start - ROUTINE_CHART_POINTS : 0;
959	      g_ui.history_follow_latest = false;
960	    }
961	  else
962	    {
963	      uint8_t next = g_ui.history_start + ROUTINE_CHART_POINTS;
964	      g_ui.history_start = next < latest ? next : latest;
965	      g_ui.history_follow_latest = g_ui.history_start == latest;
966	    }
967	
968	  g_ui.history_dirty = true;
969	  routine_ui_update(&g_ui.snapshot);
970	}
