972	static void routine_chart_event_cb(lv_event_t *event)
973	{
974	  if (lv_event_get_code(event) == LV_EVENT_RELEASED ||
975	      lv_event_get_code(event) == LV_EVENT_VALUE_CHANGED)
976	    {
977	      uint32_t id = lv_chart_get_pressed_point(g_ui.chart);
978	      uint8_t history_id;
979	      int32_t value;
980	
981	      if (id == LV_CHART_POINT_NONE || id >= ROUTINE_CHART_POINTS)
982	        {
983	          return;
984	        }
985	
986	      history_id = g_ui.history_start + id;
987	      if (history_id >= g_ui.snapshot.temperature_history_count)
988	        {
989	          return;
990	        }
991	
992	      value = g_ui.snapshot.temperature_history[history_id];
993	      if (value == ROUTINE_HISTORY_INVALID)
994	        {
995	          snprintf(g_ui.chart_selection_buffer,
996	                   sizeof(g_ui.chart_selection_buffer), "%02u:00  --",
997	                   g_ui.snapshot.temperature_history_hour[history_id]);
998	        }
999	      else
1000	        {
1001	          char temperature[20];
1002	          routine_format_signed_x100(temperature, sizeof(temperature),
1003	                                     value, " C");
1004	          snprintf(g_ui.chart_selection_buffer,
1005	                   sizeof(g_ui.chart_selection_buffer), "%02u:00  %s",
1006	                   g_ui.snapshot.temperature_history_hour[history_id],
1007	                   temperature);
1008	        }
1009	
1010	      lv_label_set_text_static(g_ui.chart_selection,
1011	                               g_ui.chart_selection_buffer);
1012	    }
1013	}
