1105	    {
1106	      return OK;
1107	    }
1108	
1109	#if LV_USE_FS_POSIX
1110	  char path[160];
1111	  int length = snprintf(path, sizeof(path), "%c:%s",
1112	                        (char)LV_FS_POSIX_LETTER, options->font_path);
1113	  if (length < 0 || length >= sizeof(path))
1114	    {
1115	      return -ENAMETOOLONG;
1116	    }
1117	
1118	  g_ui.text_font = lv_binfont_create(path);
1119	  if (g_ui.text_font == NULL)
1120	    {
1121	      syslog(LOG_ERR,
1122	             "routine_mgr: cannot load Chinese font %s; use --english\n",
1123	             path);
1124	      return -ENOENT;
1125	    }
1126	#else
1127	  return -ENOSYS;
1128	#endif
1129	
1130	  return OK;
1131	}
