102	static int routine_parse_uint(const char *text, unsigned int minimum,
103	                              unsigned int maximum, unsigned int *value)
104	{
105	  char *end;
106	  unsigned long parsed;
107	
108	  errno = 0;
109	  parsed = strtoul(text, &end, 10);
110	  if (errno != 0 || *text == '\0' || *end != '\0' ||
111	      parsed < minimum || parsed > maximum)
112	    {
113	      return -EINVAL;
114	    }
115	
116	  *value = parsed;
117	  return 0;
118	}
