133	static int routine_parse_options(int argc, FAR char *argv[],
134	                                 struct routine_options_s *options)
135	{
136	  unsigned int value;
137	  int i;
138	  int ret;
139	
140	  memset(options, 0, sizeof(*options));
141	  options->font_path = CONFIG_ROUTINE_MANAGER_FONT_PATH;
142	  options->rate = CONFIG_ROUTINE_MANAGER_DEMO_RATE;
143	  options->language = ROUTINE_UI_LANGUAGE_CHINESE;
144	
145	  for (i = 1; i < argc; i++)
146	    {
147	      if (strcmp(argv[i], "--demo") == 0)
148	        {
149	          options->demo = true;
150	        }
151	      else if (strcmp(argv[i], "--chinese") == 0)
152	        {
153	          ret = routine_set_language(options, ROUTINE_UI_LANGUAGE_CHINESE);
154	          if (ret < 0)
155	            {
156	              fprintf(stderr,
157	                      "routine_mgr: conflicting language option: %s\n",
158	                      argv[i]);
159	              return ret;
160	            }
161	        }
162	      else if (strcmp(argv[i], "--english") == 0 ||
163	               strcmp(argv[i], "--ascii") == 0)
164	        {
165	          ret = routine_set_language(options, ROUTINE_UI_LANGUAGE_ENGLISH);
166	          if (ret < 0)
167	            {
168	              fprintf(stderr,
169	                      "routine_mgr: conflicting language option: %s\n",
170	                      argv[i]);
171	              return ret;
172	            }
173	        }
174	      else if (strcmp(argv[i], "--selftest") == 0)
175	        {
176	          options->selftest = true;
177	        }
178	      else if (strcmp(argv[i], "--help") == 0)
179	        {
180	          routine_usage();
181	          return 1;
182	        }
183	      else if (strcmp(argv[i], "--font") == 0 && i + 1 < argc)
184	        {
185	          options->font_path = argv[++i];
186	        }
187	      else if (strcmp(argv[i], "--rate") == 0 && i + 1 < argc)
188	        {
189	          ret = routine_parse_uint(argv[++i], 1, 60, &value);
190	          if (ret < 0)
191	            {
192	              return ret;
193	            }
194	
195	          options->rate = value;
196	          options->rate_set = true;
197	        }
198	      else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc)
199	        {
200	          ret = routine_parse_uint(argv[++i], 1, 86400, &value);
201	          if (ret < 0)
202	            {
203	              return ret;
204	            }
205	
206	          options->duration = value;
207	        }
208	      else
209	        {
210	          fprintf(stderr, "routine_mgr: unknown or incomplete option: %s\n",
211	                  argv[i]);
212	          return -EINVAL;
213	        }
214	    }
215	
216	  if (options->rate_set && !options->demo)
217	    {
218	      fprintf(stderr, "routine_mgr: --rate requires --demo\n");
219	      return -EINVAL;
220	    }
221	
222	  return 0;
223	}
