735	int audio_service_shutdown(FAR struct audio_service_s *service)
736	{
737	  if (service == NULL || !service->initialized)
738	    {
739	      return OK;
740	    }
741	
742	  pthread_mutex_lock(&service->lock);
743	  service->shutdown_requested = true;
744	  service->cancel_requested = true;
745	  service->generation++;
746	  pthread_cond_signal(&service->cond);
747	  pthread_mutex_unlock(&service->lock);
748	
749	  if (service->thread_created)
750	    {
751	      pthread_join(service->thread, NULL);
752	    }
753	
754	  unlink(service->config.record_path);
755	  unlink(service->config.reply_path);
756	  pthread_cond_destroy(&service->cond);
757	  pthread_mutex_destroy(&service->lock);
758	  memset(service, 0, sizeof(*service));
759	  return OK;
760	}
