36	static void audio_service_publish(FAR struct audio_service_s *service,
37	                                  enum audio_service_state_e state,
38	                                  enum audio_service_error_e error)
39	{
40	  pthread_mutex_lock(&service->lock);
41	  service->state = state;
42	  service->error = error;
43	  if (state == AUDIO_SERVICE_ERROR)
44	    {
45	      service->outcome = AUDIO_SERVICE_OUTCOME_FAILED;
46	    }
47	
48	  service->sequence++;
49	  pthread_mutex_unlock(&service->lock);
50	}
51	
52	static bool audio_service_cancelled(FAR struct audio_service_s *service,
53	                                    uint32_t generation)
54	{
55	  bool cancelled;
56	
57	  pthread_mutex_lock(&service->lock);
58	  cancelled = service->shutdown_requested || service->cancel_requested ||
59	              generation != service->generation;
60	  pthread_mutex_unlock(&service->lock);
61	  return cancelled;
62	}
63	
64	static void audio_service_finish_idle(FAR struct audio_service_s *service,
65	                                      uint32_t generation,
66	                                      enum audio_service_outcome_e outcome)
67	{
68	  pthread_mutex_lock(&service->lock);
69	  if (generation == service->generation ||
70	      (outcome == AUDIO_SERVICE_OUTCOME_CANCELLED &&
71	       service->cancel_requested))
72	    {
73	      service->state = AUDIO_SERVICE_IDLE;
74	      service->error = AUDIO_SERVICE_ERROR_NONE;
75	      service->outcome = outcome;
76	      service->cancel_requested = false;
77	      service->sequence++;
78	      pthread_cond_signal(&service->cond);
79	    }
80	
81	  pthread_mutex_unlock(&service->lock);
82	}
