84	static int audio_service_capture(FAR struct audio_service_s *service,
85	                                 uint32_t generation)
86	{
87	  struct timespec delay;
88	  uint32_t elapsed;
89	  int ret;
90	
91	  service->recorder = nxrecorder_create();
92	  if (service->recorder == NULL)
93	    {
94	      return -ENOMEM;
95	    }
96	
97	  ret = nxrecorder_setdevice(service->recorder,
98	                             service->config.capture_device);
99	  if (ret < 0)
100	    {
101	      nxrecorder_release(service->recorder);
102	      service->recorder = NULL;
103	      return ret;
104	    }
105	
106	  ret = nxrecorder_recordinternal(service->recorder,
107	                                  service->config.record_path,
108	                                  AUDIO_FMT_PCM,
109	                                  AUDIO_SERVICE_CAPTURE_CHANNELS,
110	                                  AUDIO_SERVICE_BITS_PER_SAMPLE,
111	                                  AUDIO_SERVICE_SAMPLE_RATE,
112	                                  AUDIO_SERVICE_CAPTURE_CHMAP);
113	  if (ret < 0)
114	    {
115	      nxrecorder_release(service->recorder);
116	      service->recorder = NULL;
117	      return ret;
118	    }
119	
120	  delay.tv_sec = 0;
121	  delay.tv_nsec = AUDIO_SERVICE_POLL_MS * 1000000;
122	  for (elapsed = 0; elapsed < service->config.record_ms;
123	       elapsed += AUDIO_SERVICE_POLL_MS)
124	    {
125	      if (audio_service_cancelled(service, generation))
126	        {
127	          break;
128	        }
129	
130	      nanosleep(&delay, NULL);
131	    }
132	
133	  ret = nxrecorder_stop(service->recorder);
134	  nxrecorder_release(service->recorder);
135	  service->recorder = NULL;
136	  return ret;
137	}
