134	static int wifi_manager_dhcp(FAR struct wifi_connect_result_s *result)
135	{
136	  int ret;
137	
138	  errno = 0;
139	  ret = netlib_obtain_ipv4addr(WIFI_MANAGER_INTERFACE);
140	  if (ret < 0)
141	    {
142	      result->stage = WIFI_MANAGER_STAGE_DHCP;
143	      result->error = wifi_manager_normalize_error(ret);
144	      return result->error;
145	    }
146	
147	  return OK;
148	}
