150	static int wifi_manager_connect(FAR const struct wifi_config_s *config,
151	                                FAR struct wifi_connect_result_s *result)
152	{
153	  int socket_fd;
154	  int ret;
155	  int retry;
156	
157	  result->stage = NULL;
158	  result->error = OK;
159	
160	  errno = 0;
161	  ret = netlib_ifup(WIFI_MANAGER_INTERFACE);
162	  if (ret < 0)
163	    {
164	      result->stage = WIFI_MANAGER_STAGE_IFUP;
165	      result->error = wifi_manager_normalize_error(ret);
166	      return result->error;
167	    }
168	
169	  errno = 0;
170	  socket_fd = wapi_make_socket();
171	  if (socket_fd < 0)
172	    {
173	      result->stage = WIFI_MANAGER_STAGE_SOCKET;
174	      result->error = wifi_manager_normalize_error(socket_fd);
175	      return result->error;
176	    }
177	
178	  ret = wapi_set_mode(socket_fd, WIFI_MANAGER_INTERFACE,
179	                      WAPI_MODE_MANAGED);
180	  if (ret < 0)
181	    {
182	      result->stage = WIFI_MANAGER_STAGE_MODE;
183	      goto out;
184	    }
185	
186	  ret = wpa_driver_wext_set_auth_param(socket_fd,
187	                                       WIFI_MANAGER_INTERFACE,
188	                                       IW_AUTH_WPA_VERSION,
189	                                       IW_AUTH_WPA_VERSION_WPA2);
190	  if (ret < 0)
191	    {
192	      result->stage = WIFI_MANAGER_STAGE_AUTH;
193	      goto out;
194	    }
195	
196	  ret = wpa_driver_wext_set_auth_param(socket_fd,
197	                                       WIFI_MANAGER_INTERFACE,
198	                                       IW_AUTH_CIPHER_PAIRWISE,
199	                                       IW_AUTH_CIPHER_CCMP);
200	  if (ret < 0)
201	    {
202	      result->stage = WIFI_MANAGER_STAGE_AUTH;
203	      goto out;
204	    }
205	
206	  ret = wpa_driver_wext_set_key_ext(socket_fd, WIFI_MANAGER_INTERFACE,
207	                                    WPA_ALG_CCMP, config->password,
208	                                    strlen(config->password));
209	  if (ret < 0)
210	    {
211	      result->stage = WIFI_MANAGER_STAGE_KEY;
212	      goto out;
213	    }
214	
215	  ret = wapi_set_essid(socket_fd, WIFI_MANAGER_INTERFACE, config->ssid,
216	                       WAPI_ESSID_ON);
217	  if (ret < 0)
218	    {
219	      result->stage = WIFI_MANAGER_STAGE_ESSID;
220	      goto out;
221	    }
222	
223	  ret = -ETIMEDOUT;
224	  result->stage = WIFI_MANAGER_STAGE_ASSOC;
225	  for (retry = 0; retry < WIFI_MANAGER_ASSOC_RETRIES; retry++)
226	    {
227	      if (wifi_manager_ap_connected(socket_fd))
228	        {
229	          ret = OK;
230	          break;
231	        }
232	
233	      sleep(1);
234	    }
235	
236	out:
237	  close(socket_fd);
238	  if (ret < 0)
239	    {
240	      result->error = wifi_manager_normalize_error(ret);
241	      return result->error;
242	    }
243	
244	  return wifi_manager_dhcp(result);
245	}
