247	int main(int argc, FAR char *argv[])
248	{
249	  struct wifi_config_s active_config;
250	  struct wifi_config_s pending_config;
251	  struct wifi_connect_result_s result;
252	  enum wifi_config_state_e state = WIFI_CONFIG_STATE_UNKNOWN;
253	  FAR const char *last_failure_stage = NULL;
254	  unsigned int backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
255	  unsigned int retry_wait = 0;
256	  int last_failure = OK;
257	  int socket_fd;
258	  int ret;
259	  bool active_valid = false;
260	  bool associated;

247	int main(int argc, FAR char *argv[])
248	{
249	  struct wifi_config_s active_config;
250	  struct wifi_config_s pending_config;
251	  struct wifi_connect_result_s result;
252	  enum wifi_config_state_e state = WIFI_CONFIG_STATE_UNKNOWN;
253	  FAR const char *last_failure_stage = NULL;
254	  unsigned int backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
255	  unsigned int retry_wait = 0;
256	  int last_failure = OK;
257	  int socket_fd;
258	  int ret;
259	  bool active_valid = false;
260	  bool associated;
261	
262	  memset(&active_config, 0, sizeof(active_config));
263	  memset(&pending_config, 0, sizeof(pending_config));
264	  syslog(LOG_INFO, "wifi_manager: waiting for Wi-Fi configuration\n");
265	
266	  for (;;)
267	    {
268	      ret = wifi_manager_read_config(&pending_config);
269	      if (ret == -ENOENT)
270	        {
271	          if (state != WIFI_CONFIG_STATE_MISSING)
272	            {
273	              syslog(LOG_INFO,
274	                     "wifi_manager: configuration not present; idle\n");
275	            }
276	
277	          state = WIFI_CONFIG_STATE_MISSING;
278	          wifi_config_clear(&pending_config);
279	          wifi_config_clear(&active_config);
280	          active_valid = false;
281	          retry_wait = 0;
282	          last_failure = OK;
283	          last_failure_stage = NULL;
284	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
285	          continue;
286	        }
287	      else if (ret < 0)
288	        {
289	          if (state != WIFI_CONFIG_STATE_INVALID)
290	            {
291	              syslog(LOG_WARNING,
292	                     "wifi_manager: configuration is invalid; idle\n");
293	            }
294	
295	          state = WIFI_CONFIG_STATE_INVALID;
296	          wifi_config_clear(&pending_config);
297	          wifi_config_clear(&active_config);
298	          active_valid = false;
299	          retry_wait = 0;
300	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
301	          continue;
302	        }
303	
304	      state = WIFI_CONFIG_STATE_VALID;
305	      if (!active_valid ||
306	          !wifi_config_equal(&pending_config, &active_config))
307	        {
308	          wifi_config_clear(&active_config);
309	          active_config = pending_config;
310	          memset(&pending_config, 0, sizeof(pending_config));
311	          active_valid = true;
312	          backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
313	          retry_wait = 0;
314	          last_failure = OK;
315	          last_failure_stage = NULL;
316	          syslog(LOG_INFO, "wifi_manager: applying new configuration\n");
317	        }
318	      else
319	        {
320	          wifi_config_clear(&pending_config);
321	        }
322	
323	      if (retry_wait > 0)
324	        {
325	          retry_wait = retry_wait > WIFI_MANAGER_CONFIG_POLL_SEC ?
326	                       retry_wait - WIFI_MANAGER_CONFIG_POLL_SEC : 0;
327	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
328	          continue;
329	        }
330	
331	      socket_fd = wapi_make_socket();
332	      associated = socket_fd >= 0 &&
333	                   wifi_manager_ap_connected(socket_fd);
334	      if (socket_fd >= 0)
335	        {
336	          close(socket_fd);
337	        }
338	
339	      if (associated && wifi_manager_ipv4_ready())
340	        {
341	          backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
342	          last_failure = OK;
343	          last_failure_stage = NULL;
344	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
345	          continue;
346	        }
347	
348	      if (associated)
349	        {
350	          ret = wifi_manager_dhcp(&result);
351	        }
352	      else
353	        {
354	          ret = wifi_manager_connect(&active_config, &result);
355	        }
356	
357	      if (ret == 0)
358	        {
359	          backoff = WIFI_MANAGER_CONFIG_POLL_SEC;
360	          last_failure = OK;
361	          last_failure_stage = NULL;
362	          syslog(LOG_INFO, "wifi_manager: connected\n");
363	          sleep(WIFI_MANAGER_CONFIG_POLL_SEC);
364	          continue;
365	        }
366	
367	      if (ret != last_failure || result.stage != last_failure_stage)
368	        {
369	          syslog(LOG_WARNING,
370	                 "wifi_manager: %s failed (%d); retry in %u seconds\n",
371	                 result.stage == NULL ? "connection" : result.stage,
372	                 ret, backoff);
373	          last_failure = ret;
374	          last_failure_stage = result.stage;
375	        }
376	
377	      retry_wait = backoff;
378	      if (backoff < WIFI_MANAGER_BACKOFF_MAX_SEC)
379	        {
380	          backoff *= 2;
381	          if (backoff > WIFI_MANAGER_BACKOFF_MAX_SEC)
382	            {
383	              backoff = WIFI_MANAGER_BACKOFF_MAX_SEC;
384	            }
385	        }
386	    }
387	
388	  return 0;
389	}
