73	static void routine_sort_schedule(struct routine_snapshot_s *snapshot)
74	{
75	  struct routine_schedule_item_s item;
76	  uint8_t i;
77	  uint8_t j;
78	
79	  for (i = 1; i < snapshot->schedule_count; i++)
80	    {
81	      item = snapshot->schedule[i];
82	      j = i;
83	      while (j > 0 &&
84	             routine_item_minutes(&snapshot->schedule[j - 1]) >
85	             routine_item_minutes(&item))
86	        {
87	          snapshot->schedule[j] = snapshot->schedule[j - 1];
88	          j--;
89	        }
90	
91	      snapshot->schedule[j] = item;
92	    }
93	}
