static int routine_get_local_clock(struct routine_clock_s *clock)
{
  struct tm local_time;
  time_t wall_time;

  if (clock == NULL)
    {
      return -EINVAL;
    }

  wall_time = time(NULL);
  if (wall_time < 0 || localtime_r(&wall_time, &local_time) == NULL ||
      local_time.tm_year + 1900 < 2020)
    {
      memset(clock, 0, sizeof(*clock));
      return -ENODATA;
    }

  clock->day = (local_time.tm_year + 1900) * 366 + local_time.tm_yday;
  clock->hour = local_time.tm_hour;
  clock->minute = local_time.tm_min;
  clock->valid = true;
  return OK;
}

