238	static int routine_enqueue_due(struct routine_model_s *model,
239	                               struct routine_schedule_item_s *item)
240	{
241	  struct routine_due_event_s *event;
242	  uint8_t tail;
243	  uint8_t bit = 1u << item->id;
244	
245	  if ((model->due_queued_mask & bit) != 0 || item->notified ||
246	      item->completed || item->reminder_count >= ROUTINE_REMINDER_LIMIT)
247	    {
248	      return OK;
249	    }
250	
251	  if (model->due_count >= ROUTINE_DUE_QUEUE_MAX)
252	    {
253	      return -ENOSPC;
254	    }
255	
256	  tail = (model->due_head + model->due_count) % ROUTINE_DUE_QUEUE_MAX;
257	  event = &model->due_queue[tail];
258	  memset(event, 0, sizeof(*event));
259	  item->notified = true;
260	  item->reminder_count++;
261	  model->snapshot.schedule_due_sequence++;
262	  if (model->snapshot.schedule_due_sequence == 0)
263	    {
264	      model->snapshot.schedule_due_sequence++;
265	    }
266	
267	  event->sequence = model->snapshot.schedule_due_sequence;
268	  item->active_due_sequence = event->sequence;
269	  event->due_day = item->due_day;
270	  event->schedule_id = item->id;
271	  event->text_id = item->text_id;
272	  event->hour = item->hour;
273	  event->minute = item->minute;
274	  event->reminder_count = item->reminder_count;
275	  model->due_count++;
276	  model->due_queued_mask |= bit;
277	  return OK;
278	}
