280	static void routine_detect_due(struct routine_model_s *model,
281	                               int64_t old_time, int64_t new_time)
282	{
283	  struct routine_snapshot_s *snapshot = &model->snapshot;
284	  uint8_t i;
285	
286	  if (new_time <= old_time)
287	    {
288	      return;
289	    }
290	
291	  for (i = 0; i < snapshot->schedule_count; i++)
292	    {
293	      int64_t due = routine_item_minutes(&snapshot->schedule[i]);
294	
295	      if (due > old_time && due <= new_time)
296	        {
297	          routine_enqueue_due(model, &snapshot->schedule[i]);
298	        }
299	    }
300	}
