302	static void routine_advance_history(struct routine_model_s *model,
303	                                    int64_t old_time, int64_t new_time)
304	{
305	  struct routine_snapshot_s *snapshot = &model->snapshot;
306	  int64_t old_hour = old_time / 60;
307	  int64_t new_hour = new_time / 60;
308	  int64_t hour;
309	  int32_t value;
310	
311	  if (new_hour <= old_hour)
312	    {
313	      return;
314	    }
315	
316	  if (new_hour - old_hour > ROUTINE_TREND_POINTS)
317	    {
318	      old_hour = new_hour - ROUTINE_TREND_POINTS;
319	      snapshot->temperature_history_count = 0;
320	    }
321	
322	  value = model->environment_attached &&
323	          (snapshot->live_mask & ENV_METRIC_TEMPERATURE) == 0 ?
324	          ROUTINE_HISTORY_INVALID : snapshot->temperature_x100;
325	  for (hour = old_hour + 1; hour <= new_hour; hour++)
326	    {
327	      routine_history_append(snapshot, value, hour % 24);
328	    }
329	}
