553	int voice_reply_build(FAR const char *asset_dir,
554	                      FAR const char *output_path,
555	                      enum voice_reply_type_e type,
556	                      FAR const struct voice_reply_values_s *values,
557	                      FAR uint32_t *duration_ms)
558	{
559	  const char *parts[VOICE_REPLY_MAX_PARTS];
560	  uint64_t bytes = 0;
561	  size_t count = 0;
562	  size_t i;
563	  int output_fd;
564	  int ret;
565	
566	  if (asset_dir == NULL || output_path == NULL || values == NULL)
567	    {
568	      return -EINVAL;
569	    }
570	
571	  ret = voice_reply_collect(type, values, parts, &count);
572	  if (ret < 0)
573	    {
574	      return ret;
575	    }
576	
577	  output_fd = open(output_path, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC,
578	                   0644);
579	  if (output_fd < 0)
580	    {
581	      return -errno;
582	    }
583	
584	  for (i = 0; i < count; i++)
585	    {
586	      ret = voice_reply_append(asset_dir, parts[i], output_fd, &bytes);
587	      if (ret < 0)
588	        {
589	          close(output_fd);
590	          unlink(output_path);
591	          return ret;
592	        }
593	    }
594	
595	  if (close(output_fd) < 0)
596	    {
597	      ret = -errno;
598	      unlink(output_path);
599	      return ret;
600	    }
601	
602	  if (duration_ms != NULL)
603	    {
604	      *duration_ms = (bytes + VOICE_REPLY_BYTES_PER_MS - 1) /
605	                     VOICE_REPLY_BYTES_PER_MS;
606	    }
607	
608	  return OK;
609	}
