107	static int routine_parse_uint(const char *text, unsigned int minimum,
108	                              unsigned int maximum, unsigned int *value)
109	{
110	  char *end;
111	  unsigned long parsed;
112	
113	  errno = 0;
114	  parsed = strtoul(text, &end, 10);
115	  if (errno != 0 || *text == '\0' || *end != '\0' ||
116	      parsed < minimum || parsed > maximum)
117	    {
118	      return -EINVAL;
119	    }
120	
121	  *value = parsed;
122	  return 0;
123	}
