125	static int routine_set_language(struct routine_options_s *options,
126	                                enum routine_ui_language_e language)
127	{
128	  if (options->language_set && options->language != language)
129	    {
130	      return -EINVAL;
131	    }
132	
133	  options->language = language;
134	  options->language_set = true;
135	  return 0;
136	}
