138	static int routine_parse_options(int argc, FAR char *argv[],
139	                                 struct routine_options_s *options)
140	{
141	  unsigned int value;
142	  int i;
143	  int ret;
144	
145	  memset(options, 0, sizeof(*options));
146	  options->font_path = CONFIG_ROUTINE_MANAGER_FONT_PATH;
147	  options->rate = CONFIG_ROUTINE_MANAGER_DEMO_RATE;
148	  options->language = ROUTINE_UI_LANGUAGE_CHINESE;
149	
150	  for (i = 1; i < argc; i++)
151	    {
152	      if (strcmp(argv[i], "--demo") == 0)
153	        {
154	          options->demo = true;
155	        }
156	      else if (strcmp(argv[i], "--chinese") == 0)
157	        {
158	          ret = routine_set_language(options, ROUTINE_UI_LANGUAGE_CHINESE);
159	          if (ret < 0)
160	            {
161	              fprintf(stderr,
162	                      "routine_mgr: conflicting language option: %s\n",
163	                      argv[i]);
164	              return ret;
165	            }
166	        }
167	      else if (strcmp(argv[i], "--english") == 0 ||
168	               strcmp(argv[i], "--ascii") == 0)
169	        {
170	          ret = routine_set_language(options, ROUTINE_UI_LANGUAGE_ENGLISH);
171	          if (ret < 0)
172	            {
173	              fprintf(stderr,
174	                      "routine_mgr: conflicting language option: %s\n",
175	                      argv[i]);
176	              return ret;
177	            }
178	        }
179	      else if (strcmp(argv[i], "--selftest") == 0)
180	        {
181	          options->selftest = true;
182	        }
183	      else if (strcmp(argv[i], "--help") == 0)
184	        {
185	          routine_usage();
186	          return 1;
187	        }
188	      else if (strcmp(argv[i], "--font") == 0 && i + 1 < argc)
189	        {
190	          options->font_path = argv[++i];
191	        }
192	      else if (strcmp(argv[i], "--rate") == 0 && i + 1 < argc)
193	        {
194	          ret = routine_parse_uint(argv[++i], 1, 60, &value);
195	          if (ret < 0)
196	            {
197	              return ret;
198	            }
199	
200	          options->rate = value;
201	          options->rate_set = true;
202	        }
203	      else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc)
204	        {
205	          ret = routine_parse_uint(argv[++i], 1, 86400, &value);
206	          if (ret < 0)
207	            {
208	              return ret;
209	            }
210	
211	          options->duration = value;
212	        }
213	      else
214	        {
215	          fprintf(stderr, "routine_mgr: unknown or incomplete option: %s\n",
216	                  argv[i]);
217	          return -EINVAL;
218	        }
219	    }
220	
221	  if (options->rate_set && !options->demo)
222	    {
223	      fprintf(stderr, "routine_mgr: --rate requires --demo\n");
224	      return -EINVAL;
225	    }
226	
227	  return 0;
228	}
