152	static int audio_service_play(FAR struct audio_service_s *service,
153	                              uint32_t generation,
154	                              uint32_t duration_ms)
155	{
156	  struct timespec delay;
157	  uint16_t nxplayer_volume;
158	  uint32_t elapsed;
159	  bool cancelled;
160	  bool timed_out;
161	  int ret;
162	
163	  service->player = nxplayer_create();
164	  if (service->player == NULL)
165	    {
166	      return -ENOMEM;
167	    }
168	
169	  ret = nxplayer_setdevice(service->player,
170	                           service->config.playback_device);
171	  if (ret < 0)
172	    {
173	      nxplayer_release(service->player);
174	      service->player = NULL;
175	      return ret;
176	    }
177	
178	#ifndef CONFIG_AUDIO_EXCLUDE_VOLUME
179	  nxplayer_volume = audio_service_nxplayer_volume(service->config.volume);
180	  syslog(LOG_INFO,
181	         "routine_mgr: playback volume=%u%% nxplayer_volume=%u\n",
182	         service->config.volume, nxplayer_volume);
183	  ret = nxplayer_setvolume(service->player, nxplayer_volume);
184	  if (ret < 0)
185	    {
186	      nxplayer_release(service->player);
187	      service->player = NULL;
188	      return ret;
189	    }
190	#endif
191	
192	  ret = nxplayer_playraw(service->player, service->config.reply_path,
193	                         AUDIO_FMT_PCM, AUDIO_FMT_UNDEF,
194	                         AUDIO_SERVICE_PLAY_CHANNELS,
195	                         AUDIO_SERVICE_BITS_PER_SAMPLE,
196	                         AUDIO_SERVICE_SAMPLE_RATE,
197	                         AUDIO_SERVICE_PLAY_CHMAP);
198	  if (ret < 0)
199	    {
200	      nxplayer_release(service->player);
201	      service->player = NULL;
202	      return ret;
203	    }
204	
205	  delay.tv_sec = 0;
206	  delay.tv_nsec = AUDIO_SERVICE_POLL_MS * 1000000;
207	  cancelled = false;
208	  timed_out = true;
209	  for (elapsed = 0; elapsed <= duration_ms + 1000;
210	       elapsed += AUDIO_SERVICE_POLL_MS)
211	    {
212	      cancelled = audio_service_cancelled(service, generation);
213	      if (cancelled || service->player->state == AUDIO_SERVICE_PLAYER_IDLE)
214	        {
215	          timed_out = false;
216	          break;
217	        }
218	
219	      nanosleep(&delay, NULL);
220	    }
221	
222	  if (service->player->state != AUDIO_SERVICE_PLAYER_IDLE)
223	    {
224	      syslog(LOG_INFO, "routine_mgr: stopping playback (%s)\n",
225	             cancelled ? "cancelled" : "timeout");
226	      ret = nxplayer_stop(service->player);
227	      if (ret < 0)
228	        {
229	          nxplayer_release(service->player);
230	          service->player = NULL;
231	          return ret;
232	        }
233	    }
234	
235	  nxplayer_release(service->player);
236	  service->player = NULL;
237	  return timed_out ? -ETIMEDOUT : OK;
238	}
