303	static void audio_service_process(FAR struct audio_service_s *service,
304	                                  uint32_t generation)
305	{
306	  struct voice_recognition_result_s recognition;
307	  struct voice_reply_values_s values;
308	  enum audio_service_request_e request;
309	  enum voice_reply_type_e reply_type;
310	  uint32_t duration_ms;
311	  uint32_t required;
312	  int ret;
313	
314	  pthread_mutex_lock(&service->lock);
315	  request = service->request;
316	  values = service->sensor.values;
317	  if (request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER)
318	    {
319	      values.schedule_text_id = service->current_reminder.text_id;
320	      values.schedule_hour = service->current_reminder.hour;
321	      values.schedule_minute = service->current_reminder.minute;
322	    }
323	
324	  pthread_mutex_unlock(&service->lock);
325	
326	  if (request != AUDIO_SERVICE_REQUEST_QUERY)
327	    {
328	      if (request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER)
329	        {
330	          required = 0;
331	          reply_type = VOICE_REPLY_SCHEDULE_REMINDER;
332	          ret = OK;
333	        }
334	      else
335	        {
336	          ret = audio_service_sensor_request_spec(request, &required,
337	                                                  &reply_type);
338	        }
339	
340	      if (ret < 0)
341	        {
342	          audio_service_publish(service, AUDIO_SERVICE_ERROR,
343	                                AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
344	          return;
345	        }
346	
347	      audio_service_publish(service, AUDIO_SERVICE_PROCESSING,
348	                            AUDIO_SERVICE_ERROR_NONE);
349	      ret = voice_reply_build(service->config.asset_dir,
350	                              service->config.reply_path,
351	                              reply_type, &values, &duration_ms);
352	      if (ret < 0)
353	        {
354	          syslog(LOG_ERR,
355	                 "routine_mgr: sensor reply request=%u build failed: %d\n",
356	                 request, ret);
357	          audio_service_publish(service, AUDIO_SERVICE_ERROR,
358	                                AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
359	          return;
360	        }
361	
362	      audio_service_publish(service, AUDIO_SERVICE_SPEAKING,
363	                            AUDIO_SERVICE_ERROR_NONE);
364	      ret = audio_service_play(service, generation, duration_ms);
365	      unlink(service->config.reply_path);
366	      if (audio_service_cancelled(service, generation))
367	        {
368	          audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
369	          return;
370	        }
371	
372	      if (ret < 0)
373	        {
374	          audio_service_publish(service, AUDIO_SERVICE_ERROR,
375	                                AUDIO_SERVICE_ERROR_PLAYBACK);
376	          return;
377	        }
378	
379	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_COMPLETED);
380	      return;
381	    }
382	
383	  audio_service_publish(service, AUDIO_SERVICE_LISTENING,
384	                        AUDIO_SERVICE_ERROR_NONE);
385	  ret = audio_service_capture(service, generation);
386	  if (audio_service_cancelled(service, generation))
387	    {
388	      unlink(service->config.record_path);
389	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
390	      return;
391	    }
392	
393	  if (ret < 0)
394	    {
395	      audio_service_publish(service, AUDIO_SERVICE_ERROR,
396	                            AUDIO_SERVICE_ERROR_CAPTURE);
397	      return;
398	    }
399	
400	  audio_service_publish(service, AUDIO_SERVICE_PROCESSING,
401	                        AUDIO_SERVICE_ERROR_NONE);
402	  ret = voice_recognizer_demo_recognize(service->config.record_path,
403	                                        &recognition);
404	  unlink(service->config.record_path);
405	  if (audio_service_cancelled(service, generation))
406	    {
407	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
408	      return;
409	    }
410	
411	  if (ret < 0 || recognition.command != VOICE_COMMAND_QUERY_TEMPERATURE)
412	    {
413	      audio_service_publish(service, AUDIO_SERVICE_ERROR,
414	                            AUDIO_SERVICE_ERROR_NO_VOICE);
415	      return;
416	    }
417	
418	  pthread_mutex_lock(&service->lock);
419	  values = service->sensor.values;
420	  service->recognition_score = recognition.score;
421	  service->semantic_verified = recognition.semantic_verified;
422	  service->has_result = true;
423	  service->sequence++;
424	  pthread_mutex_unlock(&service->lock);
425	
426	  ret = voice_reply_build(service->config.asset_dir,
427	                          service->config.reply_path,
428	                          VOICE_REPLY_TEMPERATURE, &values, &duration_ms);
429	  if (ret < 0)
430	    {
431	      syslog(LOG_ERR, "routine_mgr: failed to build voice reply: %d\n", ret);
432	      audio_service_publish(service, AUDIO_SERVICE_ERROR,
433	                            AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
434	      return;
435	    }
436	
437	  audio_service_publish(service, AUDIO_SERVICE_SPEAKING,
438	                        AUDIO_SERVICE_ERROR_NONE);
439	  ret = audio_service_play(service, generation, duration_ms);
440	  unlink(service->config.reply_path);
441	  if (audio_service_cancelled(service, generation))
442	    {
443	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
444	      return;
445	    }
446	
447	  if (ret < 0)
448	    {
449	      audio_service_publish(service, AUDIO_SERVICE_ERROR,
450	                            AUDIO_SERVICE_ERROR_PLAYBACK);
451	      return;
452	    }
453	
454	  audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_COMPLETED);
455	}
