457	static FAR void *audio_service_thread(FAR void *arg)
458	{
459	  FAR struct audio_service_s *service = arg;
460	
461	  while (true)
462	    {
463	      uint32_t generation;
464	
465	      pthread_mutex_lock(&service->lock);
466	      while (!service->start_requested && service->reminder_count == 0 &&
467	             !service->shutdown_requested)
468	        {
469	          pthread_cond_wait(&service->cond, &service->lock);
470	        }
471	
472	      if (service->shutdown_requested)
473	        {
474	          pthread_mutex_unlock(&service->lock);
475	          break;
476	        }
477	
478	      if (!service->start_requested && service->reminder_count > 0)
479	        {
480	          service->current_reminder =
481	            service->reminder_queue[service->reminder_head];
482	          service->reminder_head =
483	            (service->reminder_head + 1) % AUDIO_SERVICE_REMINDER_MAX;
484	          service->reminder_count--;
485	          service->generation++;
486	          service->request = AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER;
487	          service->state = AUDIO_SERVICE_PROCESSING;
488	          service->error = AUDIO_SERVICE_ERROR_NONE;
489	          service->outcome = AUDIO_SERVICE_OUTCOME_NONE;
490	          service->sequence++;
491	        }
492	
493	      service->start_requested = false;
494	      service->cancel_requested = false;
495	      generation = service->generation;
496	      pthread_mutex_unlock(&service->lock);
497	      audio_service_process(service, generation);
498	    }
499	
500	  return NULL;
501	}
