593	                              enum audio_service_request_e request)
594	{
595	  uint32_t required;
596	
597	  if (service == NULL || !service->initialized ||
598	      audio_service_sensor_request_spec(request, &required, NULL) < 0)
599	    {
600	      return -EINVAL;
601	    }
602	
603	  pthread_mutex_lock(&service->lock);
604	  if (service->state != AUDIO_SERVICE_IDLE &&
605	      service->state != AUDIO_SERVICE_ERROR)
606	    {
607	      pthread_mutex_unlock(&service->lock);
608	      return -EBUSY;
609	    }
610	
611	  if ((service->sensor.offline_mask & required) != 0 ||
612	      (service->sensor.warmup_mask & required) != 0 ||
613	      (service->sensor.live_mask & required) != required)
614	    {
615	      service->request = request;
616	      service->state = AUDIO_SERVICE_ERROR;
617	      service->error = AUDIO_SERVICE_ERROR_SENSOR_UNAVAILABLE;
618	      service->sequence++;
619	      pthread_mutex_unlock(&service->lock);
620	      return -ENODATA;
621	    }
622	
623	  service->generation++;
624	  service->request = request;
625	  service->start_requested = true;
626	  service->cancel_requested = false;
627	  service->state = AUDIO_SERVICE_PROCESSING;
628	  service->error = AUDIO_SERVICE_ERROR_NONE;
629	  service->outcome = AUDIO_SERVICE_OUTCOME_NONE;
630	  service->has_result = false;
631	  service->sequence++;
632	  pthread_cond_signal(&service->cond);
633	  pthread_mutex_unlock(&service->lock);
634	  return OK;
