637	int audio_service_enqueue_reminder(
638	  FAR struct audio_service_s *service,
639	  FAR const struct audio_service_reminder_s *reminder)
640	{
641	  uint8_t tail;
642	  uint8_t i;
643	
644	  if (service == NULL || reminder == NULL || !service->initialized ||
645	      reminder->sequence == 0 ||
646	      reminder->schedule_id >= AUDIO_SERVICE_REMINDER_MAX ||
647	      reminder->text_id >= AUDIO_SERVICE_REMINDER_MAX ||
648	      reminder->hour > 23 || reminder->minute > 59)
649	    {
650	      return -EINVAL;
651	    }
652	
653	  pthread_mutex_lock(&service->lock);
654	  for (i = 0; i < service->reminder_count; i++)
655	    {
656	      uint8_t index = (service->reminder_head + i) %
657	                      AUDIO_SERVICE_REMINDER_MAX;
658	      if (audio_service_reminder_equal(&service->reminder_queue[index],
659	                                       reminder))
660	        {
661	          pthread_mutex_unlock(&service->lock);
662	          return -EALREADY;
663	        }
664	    }
665	
666	  if (service->request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER &&
667	      audio_service_reminder_equal(&service->current_reminder, reminder) &&
668	      service->state != AUDIO_SERVICE_IDLE &&
669	      service->state != AUDIO_SERVICE_ERROR)
670	    {
671	      pthread_mutex_unlock(&service->lock);
672	      return -EALREADY;
673	    }
674	
675	  if (service->reminder_count >= AUDIO_SERVICE_REMINDER_MAX)
676	    {
677	      pthread_mutex_unlock(&service->lock);
678	      return -ENOSPC;
679	    }
680	
681	  tail = (service->reminder_head + service->reminder_count) %
682	         AUDIO_SERVICE_REMINDER_MAX;
683	  service->reminder_queue[tail] = *reminder;
684	  service->reminder_count++;
685	  pthread_cond_signal(&service->cond);
686	  pthread_mutex_unlock(&service->lock);
687	  return OK;
688	}
