710	int audio_service_cancel_reminder(
711	  FAR struct audio_service_s *service,
712	  FAR const struct audio_service_reminder_s *reminder)
713	{
714	  struct audio_service_reminder_s queue[AUDIO_SERVICE_REMINDER_MAX];
715	  uint8_t kept = 0;
716	  uint8_t i;
717	
718	  if (service == NULL || reminder == NULL || !service->initialized ||
719	      reminder->sequence == 0)
720	    {
721	      return -EINVAL;
722	    }
723	
724	  pthread_mutex_lock(&service->lock);
725	  for (i = 0; i < service->reminder_count; i++)
726	    {
727	      uint8_t index = (service->reminder_head + i) %
728	                      AUDIO_SERVICE_REMINDER_MAX;
729	      if (!audio_service_reminder_equal(&service->reminder_queue[index],
730	                                        reminder))
731	        {
732	          queue[kept++] = service->reminder_queue[index];
733	        }
734	    }
735	
736	  memset(service->reminder_queue, 0, sizeof(service->reminder_queue));
737	  memcpy(service->reminder_queue, queue, kept * sizeof(queue[0]));
738	  service->reminder_head = 0;
739	  service->reminder_count = kept;
740	  if (service->request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER &&
741	      audio_service_reminder_equal(&service->current_reminder, reminder) &&
742	      service->state != AUDIO_SERVICE_IDLE &&
743	      service->state != AUDIO_SERVICE_ERROR)
744	    {
745	      service->cancel_requested = true;
746	    }
747	
748	  pthread_cond_signal(&service->cond);
749	  pthread_mutex_unlock(&service->lock);
750	  return OK;
751	}
