817	int audio_service_shutdown(FAR struct audio_service_s *service)
818	{
819	  if (service == NULL || !service->initialized)
820	    {
821	      return OK;
822	    }
823	
824	  pthread_mutex_lock(&service->lock);
825	  service->shutdown_requested = true;
826	  service->cancel_requested = true;
827	  service->generation++;
828	  pthread_cond_signal(&service->cond);
829	  pthread_mutex_unlock(&service->lock);
830	
831	  if (service->thread_created)
832	    {
833	      pthread_join(service->thread, NULL);
834	    }
835	
836	  unlink(service->config.record_path);
837	  unlink(service->config.reply_path);
838	  pthread_cond_destroy(&service->cond);
839	  pthread_mutex_destroy(&service->lock);
840	  memset(service, 0, sizeof(*service));
841	  return OK;
842	}
