916	/****************************************************************************
917	 * Name: sunxi_audio_stop
918	 *
919	 * Description:
920	 *   Stop the configured operation (audio streaming, volume disabled, etc.).
921	 *
922	 ****************************************************************************/
923	
924	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
925	#  ifdef CONFIG_AUDIO_MULTI_SESSION
926	static int sunxi_audio_stop(FAR struct audio_lowerhalf_s *dev, FAR void *session)
927	#  else
928	static int sunxi_audio_stop(FAR struct audio_lowerhalf_s *dev)
929	#  endif
930	{
931		FAR struct sunxi_dev_s *priv = (FAR struct sunxi_dev_s *)dev;
932		struct audio_msg_s term_msg;
933		int ret = 0;
934		unsigned int prio;
935		syslog(LOG_INFO, "%d, %s\n", __LINE__, __func__);
936	
937		if (priv->index == AW_AUDIO_CODEC)
938			prio = CONFIG_AW_AUDIO_CODEC_MSG_PRIO;
939		else if (priv->index == AW_AUDIO_DMIC)
940			prio = CONFIG_AW_AUDIO_DMIC_MSG_PRIO;
941		else {
942			ret = -EINVAL;
943			syslog(LOG_ERR, "index: %d err\n", priv->index);
944			return ret;
945		}
946	
947		/* Send a message to stop all audio streaming */
948		term_msg.msg_id = AUDIO_MSG_STOP;
