1593				case AUDIO_MSG_COMPLETE:
1594				syslog(LOG_INFO,"AUDIO_MSG_COMPLETE\n");
1595				break;
1596	
1597				default:
1598				syslog(LOG_ERR, "ERROR: Ignoring message ID %d\n", msg.msg_id);
