1620			priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, OK);
1621	#endif
1622		}
1623		nxmutex_unlock(&priv->pendlock);
1624	
1625		/* Close the message queue */
1626		file_mq_close(&priv->mq);
1627		file_mq_unlink(priv->mqname);
1628	
1629	  /* Send an AUDIO_MSG_COMPLETE message to the client */
1630	#ifdef CONFIG_AUDIO_MULTI_SESSION
1631		priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, NULL);
1632	#else
1633		priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
1634	#endif
