670	static int audio_stop(FAR struct file *filep, FAR void *session)
671	#else
672	static int audio_stop(FAR struct file *filep)
673	#endif
674	{
675	  FAR struct inode *inode = filep->f_inode;
676	  FAR struct audio_upperhalf_s *upper = inode->i_private;
677	  FAR struct audio_lowerhalf_s *lower = upper->dev;
678	  FAR struct audio_openpriv_s *priv = filep->f_priv;
679	  int nstate;
