681	  int ret;
682	
683	  DEBUGASSERT(upper != NULL && lower->ops->stop != NULL);
684	
685	  nstate = audio_getnstate(upper, priv);
686	  if ((upper->status->state == AUDIO_STATE_RUNNING ||
687	       upper->status->state == AUDIO_STATE_PAUSED) &&
688	      nstate == AUDIO_STATE_OPEN)
689	    {
690	      audinfo("stop: nstate=%d status=%d\n", nstate, upper->status->state);
691	      tstate = upper->status->state;
692	      audio_setstate(upper, AUDIO_STATE_DRAINING);
693	#ifdef CONFIG_AUDIO_MULTI_SESSION
694	      ret = lower->ops->stop(lower, session);
695	#else
696	      ret = lower->ops->stop(lower);
697	#endif
698	      if (ret != OK)
699	        {
700	          audio_setstate(upper, tstate);
701	          return ret;
702	        }
703	
704	      memset(&upper->info, 0, sizeof(upper->info));
705	    }
706	  else if (nstate == AUDIO_STATE_PAUSED)
707	    {
708	      audinfo("pause: nstate=%d status=%d\n", nstate, upper->status->state);
709	      ret = audio_pause(filep);
710	      if (ret != OK)
711	        {
712	          return ret;
713	        }
714	    }
715	
716	  priv->state = AUDIO_STATE_OPEN;
717	  return OK;
