35	static void audio_service_publish(FAR struct audio_service_s *service,
36	                                  uint32_t operation,
37	                                  enum audio_service_state_e state,
38	                                  enum audio_service_error_e error)
39	{
40	  pthread_mutex_lock(&service->lock);
41	  if (service->worker_active && service->active_operation == operation &&
42	      service->cancelled_operation != operation)
43	    {
44	      service->state = state;
45	      service->error = error;
46	      if (state == AUDIO_SERVICE_ERROR)
47	        {
48	          service->outcome = AUDIO_SERVICE_OUTCOME_FAILED;
49	          service->worker_active = false;
50	          service->active_operation = 0;
51	          pthread_cond_signal(&service->cond);
52	        }
53	
54	      service->sequence++;
55	    }
56	
57	  pthread_mutex_unlock(&service->lock);
58	}
59	
60	static bool audio_service_cancelled(FAR struct audio_service_s *service,
61	                                    uint32_t operation)
62	{
63	  bool cancelled;
64	
65	  pthread_mutex_lock(&service->lock);
66	  cancelled = service->shutdown_requested || !service->worker_active ||
67	              service->active_operation != operation ||
68	              service->cancelled_operation == operation;
69	  pthread_mutex_unlock(&service->lock);
70	  return cancelled;
71	}
