86	static void audio_service_finish_idle(FAR struct audio_service_s *service,
87	                                      uint32_t operation,
88	                                      enum audio_service_outcome_e outcome)
89	{
90	  pthread_mutex_lock(&service->lock);
91	  if (service->worker_active && service->active_operation == operation)
92	    {
93	      service->state = AUDIO_SERVICE_IDLE;
94	      service->error = AUDIO_SERVICE_ERROR_NONE;
95	      service->outcome = outcome;
96	      service->worker_active = false;
97	      service->active_operation = 0;
98	      if (service->cancelled_operation == operation)
99	        {
100	          service->cancelled_operation = 0;
101	        }
102	
103	      service->sequence++;
104	      pthread_cond_signal(&service->cond);
105	    }
106	
107	  pthread_mutex_unlock(&service->lock);
108	}
