110	static int audio_service_capture(FAR struct audio_service_s *service,
111	                                 uint32_t generation)
112	{
113	  struct timespec delay;
114	  uint32_t elapsed;
115	  int ret;
116	
117	  service->recorder = nxrecorder_create();
118	  if (service->recorder == NULL)
119	    {
120	      return -ENOMEM;
121	    }
122	
123	  ret = nxrecorder_setdevice(service->recorder,
124	                             service->config.capture_device);
125	  if (ret < 0)
126	    {
127	      nxrecorder_release(service->recorder);
128	      service->recorder = NULL;
129	      return ret;
130	    }
131	
132	  ret = nxrecorder_recordinternal(service->recorder,
133	                                  service->config.record_path,
134	                                  AUDIO_FMT_PCM,
135	                                  AUDIO_SERVICE_CAPTURE_CHANNELS,
136	                                  AUDIO_SERVICE_BITS_PER_SAMPLE,
137	                                  AUDIO_SERVICE_SAMPLE_RATE,
138	                                  AUDIO_SERVICE_CAPTURE_CHMAP);
139	  if (ret < 0)
140	    {
141	      nxrecorder_release(service->recorder);
142	      service->recorder = NULL;
143	      return ret;
144	    }
145	
146	  delay.tv_sec = 0;
147	  delay.tv_nsec = AUDIO_SERVICE_POLL_MS * 1000000;
148	  for (elapsed = 0; elapsed < service->config.record_ms;
149	       elapsed += AUDIO_SERVICE_POLL_MS)
150	    {
151	      if (audio_service_cancelled(service, generation))
152	        {
153	          break;
154	        }
155	
156	      nanosleep(&delay, NULL);
157	    }
158	
159	  ret = nxrecorder_stop(service->recorder);
160	  nxrecorder_release(service->recorder);
161	  service->recorder = NULL;
162	  return ret;
163	}
