178	static int audio_service_play(FAR struct audio_service_s *service,
179	                              uint32_t generation,
180	                              uint32_t duration_ms)
181	{
182	  struct nxplayer_status_s status;
183	  struct timespec deadline;
184	  uint16_t nxplayer_volume;
185	  uint32_t elapsed;
186	  bool cancelled;
187	  bool timed_out;
188	  int ret;
189	
190	  service->player = nxplayer_create();
191	  if (service->player == NULL)
192	    {
193	      return -ENOMEM;
194	    }
195	
196	  ret = nxplayer_setdevice(service->player,
197	                           service->config.playback_device);
198	  if (ret < 0)
199	    {
200	      nxplayer_release(service->player);
201	      service->player = NULL;
202	      return ret;
203	    }
204	
205	#ifndef CONFIG_AUDIO_EXCLUDE_VOLUME
206	  nxplayer_volume = audio_service_nxplayer_volume(service->config.volume);
207	  syslog(LOG_INFO,
208	         "routine_mgr: playback volume=%u%% nxplayer_volume=%u\n",
209	         service->config.volume, nxplayer_volume);
210	  ret = nxplayer_setvolume(service->player, nxplayer_volume);
211	  if (ret < 0)
212	    {
213	      nxplayer_release(service->player);
214	      service->player = NULL;
215	      return ret;
216	    }
217	#endif
218	
219	  if (audio_service_cancelled(service, generation))
220	    {
221	      nxplayer_release(service->player);
222	      service->player = NULL;
223	      return -ECANCELED;
224	    }
225	
226	  ret = nxplayer_playraw(service->player, service->config.reply_path,
227	                         AUDIO_FMT_PCM, AUDIO_FMT_UNDEF,
228	                         AUDIO_SERVICE_PLAY_CHANNELS,
229	                         AUDIO_SERVICE_BITS_PER_SAMPLE,
230	                         AUDIO_SERVICE_SAMPLE_RATE,
231	                         AUDIO_SERVICE_PLAY_CHMAP);
232	  if (ret < 0)
233	    {
234	      nxplayer_release(service->player);
235	      service->player = NULL;
236	      return ret;
237	    }
238	
239	  cancelled = false;
240	  timed_out = true;
241	  for (elapsed = 0; elapsed <= duration_ms + 1000;
242	       elapsed += AUDIO_SERVICE_POLL_MS)
243	    {
244	      cancelled = audio_service_cancelled(service, generation);
245	      ret = nxplayer_getstatus(service->player, &status);
246	      if (ret < 0)
247	        {
248	          break;
249	        }
250	
251	      if (cancelled || status.state == NXPLAYER_STATE_IDLE)
252	        {
253	          timed_out = false;
254	          break;
255	        }
256	
257	      clock_gettime(CLOCK_REALTIME, &deadline);
258	      deadline.tv_nsec += AUDIO_SERVICE_POLL_MS * 1000000;
259	      if (deadline.tv_nsec >= 1000000000)
260	        {
261	          deadline.tv_sec++;
262	          deadline.tv_nsec -= 1000000000;
263	        }
264	
265	      pthread_mutex_lock(&service->lock);
266	      if (!service->shutdown_requested &&
267	          service->cancelled_operation != generation)
268	        {
269	          pthread_cond_timedwait(&service->cond, &service->lock, &deadline);
270	        }
271	
272	      pthread_mutex_unlock(&service->lock);
273	    }
274	
275	  if (cancelled || timed_out || status.state != NXPLAYER_STATE_IDLE)
276	    {
277	      syslog(LOG_INFO, "routine_mgr: stopping playback (%s)\n",
278	             cancelled ? "cancelled" : "timeout");
279	      ret = nxplayer_stop(service->player);
280	      if (ret < 0)
281	        {
282	          nxplayer_release(service->player);
283	          service->player = NULL;
284	          return ret;
285	        }
286	    }
287	
288	  ret = nxplayer_getstatus(service->player, &status);
289	  nxplayer_release(service->player);
290	  service->player = NULL;
291	  if (cancelled)
292	    {
293	      return -ECANCELED;
294	    }
295	
296	  if (timed_out)
297	    {
298	      return -ETIMEDOUT;
299	    }
300	
301	  return ret < 0 ? ret : status.result;
302	}
