304	static int audio_service_sensor_request_spec(
305	  enum audio_service_request_e request, FAR uint32_t *required,
306	  FAR enum voice_reply_type_e *reply_type)
307	{
308	  switch (request)
309	    {
310	      case AUDIO_SERVICE_REQUEST_TEMPERATURE:
311	        if (required != NULL)
312	          {
313	            *required = ENV_METRIC_TEMPERATURE;
314	          }
315	
316	        if (reply_type != NULL)
317	          {
318	            *reply_type = VOICE_REPLY_TEMPERATURE;
319	          }
320	
321	        return OK;
322	
323	      case AUDIO_SERVICE_REQUEST_HUMIDITY:
324	        if (required != NULL)
325	          {
326	            *required = ENV_METRIC_HUMIDITY;
327	          }
328	
329	        if (reply_type != NULL)
330	          {
331	            *reply_type = VOICE_REPLY_HUMIDITY;
332	          }
333	
334	        return OK;
335	
336	      case AUDIO_SERVICE_REQUEST_BH1750:
337	        if (required != NULL)
338	          {
339	            *required = ENV_METRIC_LIGHT;
340	          }
341	
342	        if (reply_type != NULL)
343	          {
344	            *reply_type = VOICE_REPLY_BH1750;
345	          }
346	
347	        return OK;
348	
349	      case AUDIO_SERVICE_REQUEST_SGP30:
350	        if (required != NULL)
351	          {
352	            *required = ENV_METRIC_ECO2 | ENV_METRIC_TVOC;
353	          }
354	
355	        if (reply_type != NULL)
356	          {
357	            *reply_type = VOICE_REPLY_SGP30;
358	          }
359	
360	        return OK;
361	
362	      default:
363	        return -EINVAL;
364	    }
365	}
