367	static void audio_service_process(FAR struct audio_service_s *service,
368	                                  uint32_t generation)
369	{
370	  struct audio_service_cancel_context_s cancel_context;
371	  struct voice_recognition_result_s recognition;
372	  struct voice_reply_values_s values;
373	  enum audio_service_request_e request;
374	  enum voice_reply_type_e reply_type;
375	  uint32_t duration_ms;
376	  uint32_t required;
377	  int ret;
378	
379	  pthread_mutex_lock(&service->lock);
380	  request = service->request;
381	  values = service->sensor.values;
382	  if (request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER)
383	    {
384	      values.schedule_text_id = service->current_reminder.text_id;
385	      values.schedule_hour = service->current_reminder.hour;
386	      values.schedule_minute = service->current_reminder.minute;
387	    }
388	
389	  pthread_mutex_unlock(&service->lock);
390	  cancel_context.service = service;
391	  cancel_context.operation = generation;
392	
393	  if (request != AUDIO_SERVICE_REQUEST_QUERY)
394	    {
395	      if (request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER)
396	        {
397	          required = 0;
398	          reply_type = VOICE_REPLY_SCHEDULE_REMINDER;
399	          ret = OK;
400	        }
401	      else
402	        {
403	          ret = audio_service_sensor_request_spec(request, &required,
404	                                                  &reply_type);
405	        }
406	
407	      if (ret < 0)
408	        {
409	          audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
410	                                AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
411	          return;
412	        }
413	
414	      audio_service_publish(service, generation, AUDIO_SERVICE_PROCESSING,
415	                            AUDIO_SERVICE_ERROR_NONE);
416	      ret = voice_reply_build_cancelable(service->config.asset_dir,
417	                                         service->config.reply_path,
418	                                         reply_type, &values, &duration_ms,
419	                                         audio_service_reply_cancel,
420	                                         &cancel_context);
421	      if (ret < 0)
422	        {
423	          if (ret == -ECANCELED ||
424	              audio_service_cancelled(service, generation))
425	            {
426	              audio_service_finish_idle(service, generation,
427	                                        AUDIO_SERVICE_OUTCOME_CANCELLED);
428	              return;
429	            }
430	
431	          syslog(LOG_ERR,
432	                 "routine_mgr: sensor reply request=%u build failed: %d\n",
433	                 request, ret);
434	          audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
435	                                AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
436	          return;
437	        }
438	
439	      if (audio_service_cancelled(service, generation))
440	        {
441	          unlink(service->config.reply_path);
442	          audio_service_finish_idle(service, generation,
443	                                    AUDIO_SERVICE_OUTCOME_CANCELLED);
444	          return;
445	        }
446	
447	      audio_service_publish(service, generation, AUDIO_SERVICE_SPEAKING,
448	                            AUDIO_SERVICE_ERROR_NONE);
449	      ret = audio_service_play(service, generation, duration_ms);
450	      unlink(service->config.reply_path);
451	      if (audio_service_cancelled(service, generation))
452	        {
453	          audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
454	          return;
455	        }
456	
457	      if (ret < 0)
458	        {
459	          if (ret == -ECANCELED)
460	            {
461	              audio_service_finish_idle(service, generation,
462	                                        AUDIO_SERVICE_OUTCOME_CANCELLED);
463	              return;
464	            }
465	
466	          audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
467	                                AUDIO_SERVICE_ERROR_PLAYBACK);
468	          return;
469	        }
470	
471	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_COMPLETED);
472	      return;
473	    }
474	
475	  audio_service_publish(service, generation, AUDIO_SERVICE_LISTENING,
476	                        AUDIO_SERVICE_ERROR_NONE);
477	  ret = audio_service_capture(service, generation);
478	  if (audio_service_cancelled(service, generation))
479	    {
480	      unlink(service->config.record_path);
481	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
482	      return;
483	    }
484	
485	  if (ret < 0)
486	    {
487	      audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
488	                            AUDIO_SERVICE_ERROR_CAPTURE);
489	      return;
490	    }
491	
492	  audio_service_publish(service, generation, AUDIO_SERVICE_PROCESSING,
493	                        AUDIO_SERVICE_ERROR_NONE);
494	  ret = voice_recognizer_demo_recognize(service->config.record_path,
495	                                        &recognition);
496	  unlink(service->config.record_path);
497	  if (audio_service_cancelled(service, generation))
498	    {
499	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
500	      return;
501	    }
502	
503	  if (ret < 0 || recognition.command != VOICE_COMMAND_QUERY_TEMPERATURE)
504	    {
505	      audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
506	                            AUDIO_SERVICE_ERROR_NO_VOICE);
507	      return;
508	    }
509	
510	  pthread_mutex_lock(&service->lock);
511	  values = service->sensor.values;
512	  service->recognition_score = recognition.score;
513	  service->semantic_verified = recognition.semantic_verified;
514	  service->has_result = true;
515	  service->sequence++;
516	  pthread_mutex_unlock(&service->lock);
517	
518	  ret = voice_reply_build_cancelable(service->config.asset_dir,
519	                                     service->config.reply_path,
520	                                     VOICE_REPLY_TEMPERATURE, &values,
521	                                     &duration_ms, audio_service_reply_cancel,
522	                                     &cancel_context);
523	  if (ret < 0)
524	    {
525	      if (ret == -ECANCELED || audio_service_cancelled(service, generation))
526	        {
527	          audio_service_finish_idle(service, generation,
528	                                    AUDIO_SERVICE_OUTCOME_CANCELLED);
529	          return;
530	        }
531	
532	      syslog(LOG_ERR, "routine_mgr: failed to build voice reply: %d\n", ret);
533	      audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
534	                            AUDIO_SERVICE_ERROR_REPLY_RESOURCE);
535	      return;
536	    }
537	
538	  if (audio_service_cancelled(service, generation))
539	    {
540	      unlink(service->config.reply_path);
541	      audio_service_finish_idle(service, generation,
542	                                AUDIO_SERVICE_OUTCOME_CANCELLED);
543	      return;
544	    }
545	
546	  audio_service_publish(service, generation, AUDIO_SERVICE_SPEAKING,
547	                        AUDIO_SERVICE_ERROR_NONE);
548	  ret = audio_service_play(service, generation, duration_ms);
549	  unlink(service->config.reply_path);
550	  if (audio_service_cancelled(service, generation))
551	    {
552	      audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_CANCELLED);
553	      return;
554	    }
555	
556	  if (ret < 0)
557	    {
558	      if (ret == -ECANCELED)
559	        {
560	          audio_service_finish_idle(service, generation,
561	                                    AUDIO_SERVICE_OUTCOME_CANCELLED);
562	          return;
563	        }
564	
565	      audio_service_publish(service, generation, AUDIO_SERVICE_ERROR,
566	                            AUDIO_SERVICE_ERROR_PLAYBACK);
567	      return;
568	    }
569	
570	  audio_service_finish_idle(service, generation, AUDIO_SERVICE_OUTCOME_COMPLETED);
571	}
