573	static FAR void *audio_service_thread(FAR void *arg)
574	{
575	  FAR struct audio_service_s *service = arg;
576	
577	  while (true)
578	    {
579	      uint32_t generation;
580	
581	      pthread_mutex_lock(&service->lock);
582	      while (!service->start_requested && service->reminder_count == 0 &&
583	             !service->shutdown_requested)
584	        {
585	          pthread_cond_wait(&service->cond, &service->lock);
586	        }
587	
588	      if (service->shutdown_requested)
589	        {
590	          pthread_mutex_unlock(&service->lock);
591	          break;
592	        }
593	
594	      if (!service->start_requested && service->reminder_count > 0)
595	        {
596	          service->current_reminder =
597	            service->reminder_queue[service->reminder_head];
598	          service->reminder_head =
599	            (service->reminder_head + 1) % AUDIO_SERVICE_REMINDER_MAX;
600	          service->reminder_count--;
601	          service->generation++;
602	          service->request = AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER;
603	          service->state = AUDIO_SERVICE_PROCESSING;
604	          service->error = AUDIO_SERVICE_ERROR_NONE;
605	          service->outcome = AUDIO_SERVICE_OUTCOME_NONE;
606	          service->sequence++;
607	        }
608	
609	      service->start_requested = false;
610	      service->worker_active = true;
611	      service->active_operation = service->generation;
612	      generation = service->active_operation;
613	      pthread_mutex_unlock(&service->lock);
614	      audio_service_process(service, generation);
615	    }
616	
617	  return NULL;
618	}
