620	int audio_service_initialize(FAR struct audio_service_s *service,
621	                             FAR const struct audio_service_config_s *config)
622	{
623	  struct sched_param sched;
624	  pthread_attr_t attr;
625	  int ret;
626	
627	  if (service == NULL || config == NULL || config->capture_device == NULL ||
628	      config->playback_device == NULL || config->record_path == NULL ||
629	      config->reply_path == NULL || config->asset_dir == NULL ||
630	      config->record_ms == 0 || config->volume < 1 || config->volume > 100)
631	    {
632	      return -EINVAL;
633	    }
634	
635	  memset(service, 0, sizeof(*service));
636	  service->config = *config;
637	  service->state = AUDIO_SERVICE_IDLE;
638	  ret = pthread_mutex_init(&service->lock, NULL);
639	  if (ret != 0)
640	    {
641	      return -ret;
642	    }
643	
644	  ret = pthread_cond_init(&service->cond, NULL);
645	  if (ret != 0)
646	    {
647	      pthread_mutex_destroy(&service->lock);
648	      return -ret;
649	    }
650	
651	  pthread_attr_init(&attr);
652	  if (config->stack_size > 0)
653	    {
654	      pthread_attr_setstacksize(&attr, config->stack_size);
655	    }
656	
657	  if (config->priority > 0)
658	    {
659	      memset(&sched, 0, sizeof(sched));
660	      sched.sched_priority = config->priority;
661	      pthread_attr_setschedparam(&attr, &sched);
662	    }
663	
664	  ret = pthread_create(&service->thread, &attr, audio_service_thread, service);
665	  pthread_attr_destroy(&attr);
666	  if (ret != 0)
667	    {
668	      pthread_cond_destroy(&service->cond);
669	      pthread_mutex_destroy(&service->lock);
670	      return -ret;
671	    }
672	
673	  service->thread_created = true;
674	  service->initialized = true;
675	  return OK;
676	}
