752	int audio_service_enqueue_reminder(
753	  FAR struct audio_service_s *service,
754	  FAR const struct audio_service_reminder_s *reminder)
755	{
756	  uint8_t tail;
757	  uint8_t i;
758	
759	  if (service == NULL || reminder == NULL || !service->initialized ||
760	      reminder->sequence == 0 ||
761	      reminder->schedule_id >= AUDIO_SERVICE_REMINDER_MAX ||
762	      reminder->text_id >= AUDIO_SERVICE_REMINDER_MAX ||
763	      reminder->hour > 23 || reminder->minute > 59)
764	    {
765	      return -EINVAL;
766	    }
767	
768	  pthread_mutex_lock(&service->lock);
769	  for (i = 0; i < service->reminder_count; i++)
770	    {
771	      uint8_t index = (service->reminder_head + i) %
772	                      AUDIO_SERVICE_REMINDER_MAX;
773	      if (audio_service_reminder_equal(&service->reminder_queue[index],
774	                                       reminder))
775	        {
776	          pthread_mutex_unlock(&service->lock);
777	          return -EALREADY;
778	        }
779	    }
780	
781	  if (service->worker_active &&
782	      service->request == AUDIO_SERVICE_REQUEST_SCHEDULE_REMINDER &&
783	      audio_service_reminder_equal(&service->current_reminder, reminder))
784	    {
785	      pthread_mutex_unlock(&service->lock);
786	      return -EALREADY;
787	    }
788	
789	  if (service->reminder_count >= AUDIO_SERVICE_REMINDER_MAX)
790	    {
791	      pthread_mutex_unlock(&service->lock);
792	      return -ENOSPC;
793	    }
794	
795	  tail = (service->reminder_head + service->reminder_count) %
796	         AUDIO_SERVICE_REMINDER_MAX;
797	  service->reminder_queue[tail] = *reminder;
798	  service->reminder_count++;
799	  pthread_cond_signal(&service->cond);
800	  pthread_mutex_unlock(&service->lock);
801	  return OK;
802	}
