164	/****************************************************************************
165	 * Name: _open_with_http
166	 *
167	 *   _open_with_http() opens specified fullurl which is http:// or local file
168	 *   path and returns a file descriptor.
169	 *
170	 ****************************************************************************/
171	
172	static int _open_with_http(const char *fullurl)
173	{
174	  char relurl[CONFIG_NXPLAYER_HTTP_MAXFILENAME];
175	  char hostname[CONFIG_NXPLAYER_HTTP_MAXHOSTNAME];
176	  int  resp_chk = 0;
177	  char resp_msg[] = "\r\n\r\n";
178	  struct timeval tv;
179	  uint16_t port = 80;
180	  char buf[PATH_MAX];
181	  int  s;
182	  int  n;
183	  char c;
184	
185	  if (NULL == strstr(fullurl, "http://"))
186	    {
187	      /* assumes local file specified */
188	
189	      s = open(fullurl, O_RDONLY);
190	      return s;
191	    }
192	
193	  memset(relurl, 0, sizeof(relurl));
194	
195	  n = netlib_parsehttpurl(fullurl, &port,
196	                          hostname, sizeof(hostname) - 1,
197	                          relurl, sizeof(relurl) - 1);
198	
199	  if (OK != n)
200	    {
201	      printf("netlib_parsehttpurl() returned %d\n", n);
202	      return n;
203	    }
204	
205	  s = socket(AF_INET, SOCK_STREAM, 0);
206	  DEBUGASSERT(s != -1);
207	
208	  tv.tv_sec  = 10; /* TODO */
209	  tv.tv_usec = 0;
210	
211	  setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(struct timeval));
212	  setsockopt(s, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(struct timeval));
213	
214	  struct sockaddr_in server;
215	  server.sin_family = AF_INET;
216	  server.sin_port   = htons(port);
217	
218	  FAR struct hostent *he;
219	  he = gethostbyname(hostname);
220	
221	  memcpy(&server.sin_addr.s_addr,
222	         he->h_addr, sizeof(in_addr_t));
223	
224	  n = connect(s,
225	              (struct sockaddr *)&server,
226	              sizeof(struct sockaddr_in));
227	
228	  if (-1 == n)
229	    {
230	      close(s);
231	      return -1;
232	    }
233	
234	  /* Send GET request */
235	
236	  snprintf(buf, sizeof(buf), "GET /%s HTTP/1.0\r\n\r\n", relurl);
237	  n = write(s, buf, strlen(buf));
238	
239	  usleep(100 * 1000); /* TODO */
240	
241	  /* Check status line : e.g. "HTTP/1.x XXX" */
242	
243	  memset(buf, 0, sizeof(buf));
244	  read(s, buf, 12);
245	  n = atoi(buf + 9);
246	
247	  if (200 != n)
248	    {
249	      close(s);
250	      return -1;
251	    }
252	
253	  /* Skip response header */
254	
255	  while (1)
256	    {
257	      n = read(s, &c, 1);
258	
259	      if (1 == n)
260	        {
261	          if (resp_msg[resp_chk] == c)
262	            {
263	              resp_chk++;
264	            }
265	          else
266	            {
267	              resp_chk = 0;
268	            }
269	        }
270	
271	      if (resp_chk == 4)
272	        {
273	          break;
274	        }
275	    }
276	
277	  return s;
278	}
