790	/****************************************************************************
791	 * Name: nxplayer_jointhread
792	 ****************************************************************************/
793	
794	static void nxplayer_setstate(FAR struct nxplayer_s *pplayer,
795	                              enum nxplayer_state_e state, int result)
796	{
797	  pthread_mutex_lock(&pplayer->mutex);
798	  pplayer->state = state;
799	  pplayer->result = result;
800	  pthread_mutex_unlock(&pplayer->mutex);
801	}
802	
803	static bool nxplayer_stoprequested(FAR struct nxplayer_s *pplayer)
804	{
805	  bool stop_requested;
806	
807	  pthread_mutex_lock(&pplayer->mutex);
808	  stop_requested = pplayer->stop_requested;
809	  pthread_mutex_unlock(&pplayer->mutex);
810	  return stop_requested;
811	}
812	
813	static void nxplayer_jointhread(FAR struct nxplayer_s *pplayer)
814	{
815	  FAR void *value;
816	  int id = 0;
817	
818	  if (gettid() == pplayer->play_id)
819	    {
820	      return;
821	    }
822	
823	  pthread_mutex_lock(&pplayer->mutex);
824	
825	  if (pplayer->play_id > 0)
826	    {
827	      id = pplayer->play_id;
828	      pplayer->play_id = 0;
829	    }
830	
831	  pthread_mutex_unlock(&pplayer->mutex);
832	
833	  if (id > 0)
834	    {
835	      pthread_join(id, &value);
836	    }
837	}
838	
839	/****************************************************************************
840	 * Name: nxplayer_thread_playthread
841	 *
842	 *  This is the thread that reads the audio file file and enqueues /
843	 *  dequeues buffers to the selected and opened audio device.
844	 *
845	 ****************************************************************************/
846	
847	static FAR void *nxplayer_playthread(pthread_addr_t pvarg)
848	{
849	  FAR struct nxplayer_s   *pplayer = (FAR struct nxplayer_s *)pvarg;
850	  struct audio_msg_s      msg;
851	  struct audio_buf_desc_s buf_desc;
852	  ssize_t                 size;
853	  bool                    running = true;
854	  bool                    streaming = true;
855	  bool                    failed = false;
856	  struct ap_buffer_info_s buf_info;
857	  FAR struct ap_buffer_s  **buffers;
858	  unsigned int            prio;
859	#ifdef CONFIG_DEBUG_FEATURES
860	  int                     outstanding = 0;
861	#endif
862	  int                     x;
863	  int                     ret;
864	
865	  audinfo("Entry\n");
866	
867	  /* Query the audio device for its preferred buffer size / qty */
868	
869	  if ((ret = ioctl(pplayer->dev_fd, AUDIOIOC_GETBUFFERINFO,
870	                  (unsigned long)&buf_info)) != OK)
871	    {
872	      /* Driver doesn't report its buffer size.  Use our default. */
873	
874	      buf_info.buffer_size = CONFIG_AUDIO_BUFFER_NUMBYTES;
875	      buf_info.nbuffers = CONFIG_AUDIO_NUM_BUFFERS;
876	    }
877	
878	  /* Create array of pointers to buffers */
879	
880	  buffers = (FAR struct ap_buffer_s **)
881	    malloc(buf_info.nbuffers * sizeof(FAR void *));
882	  if (buffers == NULL)
883	    {
884	      /* Error allocating memory for buffer storage! */
885	
886	      ret = -ENOMEM;
887	      running = false;
888	      goto err_out;
889	    }
890	
891	  /* Create our audio pipeline buffers to use for queueing up data */
892	
893	  for (x = 0; x < buf_info.nbuffers; x++)
894	    {
895	      buffers[x] = NULL;
896	    }
897	
898	  for (x = 0; x < buf_info.nbuffers; x++)
899	    {
900	      /* Fill in the buffer descriptor struct to issue an alloc request */
901	
902	#ifdef CONFIG_AUDIO_MULTI_SESSION
903	      buf_desc.session = pplayer->session;
904	#endif
905	
906	      buf_desc.numbytes = buf_info.buffer_size;
907	      buf_desc.u.pbuffer = &buffers[x];
908	
909	      ret = ioctl(pplayer->dev_fd, AUDIOIOC_ALLOCBUFFER,
910	                 (unsigned long)&buf_desc);
911	      if (ret != sizeof(buf_desc))
912	        {
913	          /* Buffer alloc Operation not supported or error allocating! */
914	
915	          auderr("ERROR: Could not allocate buffer %d\n", x);
916	          running = false;
917	          goto err_out;
918	        }
919	    }
920	
921	  /* A stop can arrive after nxplayer_playraw() returns but before any audio
922	   * has been queued.  Honor it without starting the device.
923	   */
924	
925	  if (nxplayer_stoprequested(pplayer))
926	    {
927	      running = false;
928	      goto err_out;
929	    }
930	
931	  /* Fill up the pipeline with enqueued buffers */
932	
933	  for (x = 0; x < buf_info.nbuffers; x++)
934	    {
935	      /* Read the next buffer of data */
936	
937	      if (pplayer->tone.sample_rate)
938	        {
939	          /* Fill the generated tone data into apb  */
940	
941	          ret = nxplayer_filltone(&pplayer->tone, buffers[x]);
942	        }
943	      else
944	        {
945	          /* Fill the audio data of the file into apb */
946	
947	          ret = nxplayer_readbuffer(pplayer, buffers[x]);
948	        }
949	
950	      if (ret != OK)
951	        {
952	          /* nxplayer_readbuffer will return an error if there is no further
953	           * data to be read from the file.  This can happen normally if the
954	           * file is very small (less than will fit in
955	           * CONFIG_AUDIO_NUM_BUFFERS) or if an error occurs trying to read
956	           * from the file.
957	           */
958	
959	          /* We are no longer streaming data from the file */
960	
961	          streaming = false;
962	
963	          if (x == 0)
964	            {
965	              /* No buffers read?  Should never really happen.  Even in the
966	               * case of a read failure, one empty buffer containing the
967	               * AUDIO_APB_FINAL indication will be returned.
968	               */
969	
970	              running = false;
971	            }
972	        }
973	
974	      /* Enqueue buffer by sending it to the audio driver */
975	
976	      else
977	        {
978	          ret = nxplayer_enqueuebuffer(pplayer, buffers[x]);
979	          if (ret != OK)
980	            {
981	              /* Failed to enqueue the buffer.
982	               * The driver is not happy with the buffer.
983	               * Perhaps a decoder has detected something that it
984	               * does not like in the stream and has stopped streaming.
985	               * This would happen normally if we send a file in the
986	               * incorrect format to an audio decoder.
987	               *
988	               * We must stop streaming as gracefully as possible.  Close the
989	               * file so that no further data is read.
990	               */
991	
992	              close(pplayer->fd);
993	              pplayer->fd = -1;
994	
995	              /* We are no longer streaming data from the file.  Be we will
996	               * need to wait for any outstanding buffers to be recovered.
997	               *  We also still expect the audio driver to send a
998	               * AUDIO_MSG_COMPLETE message after all queued buffers have
999	               * been returned.
1000	               */
1001	
1002	               streaming = false;
1003	               failed = true;
1004	               break;
1005	            }
1006	#ifdef CONFIG_DEBUG_FEATURES
1007	          else
1008	            {
1009	              /* The audio driver has one more buffer */
1010	
1011	              outstanding++;
1012	            }
1013	#endif
1014	        }
1015	    }
1016	
1017	  audinfo("%d buffers queued, running=%d streaming=%d\n",
1018	          x, running, streaming);
1019	
1020	  /* Start the audio device.  A stop requested after buffers were queued is
1021	   * consumed by the normal playback message loop so those buffers are
1022	   * returned by the lower half before cleanup.
1023	   */
1024	
1025	  if (running && !failed)
1026	    {
1027	#ifdef CONFIG_AUDIO_MULTI_SESSION
1028	      ret = ioctl(pplayer->dev_fd, AUDIOIOC_START,
1029	                 (unsigned long)pplayer->session);
1030	#else
1031	      ret = ioctl(pplayer->dev_fd, AUDIOIOC_START, 0);
1032	#endif
1033	
1034	      if (ret < 0)
1035	        {
1036	          /* Error starting the audio stream!  We need to continue running
1037	           * in order to recover the audio buffers that have already been
1038	           * queued.
1039	           */
1040	
1041	          failed = true;
1042	        }
1043	    }
1044	
1045	  if (running && !failed)
1046	    {
1047	      /* Indicate we are playing a file unless a stop was already requested
1048	       * during asynchronous startup.
1049	       */
1050	
1051	      pthread_mutex_lock(&pplayer->mutex);
1052	      pplayer->state = pplayer->stop_requested ?
1053	                       NXPLAYER_STATE_STOPPING : NXPLAYER_STATE_PLAYING;
1054	      pthread_mutex_unlock(&pplayer->mutex);
1055	
1056	      /* Set initial parameters such as volume, bass, etc.
1057	       * REVISIT:  Shouldn't this actually be done BEFORE we start playing?
1058	       */
1059	
1060	#ifndef CONFIG_AUDIO_EXCLUDE_VOLUME
1061	      nxplayer_setvolume(pplayer, pplayer->volume);
1062	#ifndef CONFIG_AUDIO_EXCLUDE_BALANCE
1063	      nxplayer_setbalance(pplayer, pplayer->balance);
1064	#endif
1065	#endif
1066	
1067	#ifndef CONFIG_AUDIO_EXCLUDE_TONE
1068	      nxplayer_setbass(pplayer, pplayer->bass);
1069	      nxplayer_settreble(pplayer, pplayer->treble);
1070	#endif
1071	    }
1072	
1073	  /* Loop until we specifically break.  running == true means that we are
1074	   * still looping waiting for the playback to complete.  All of the file
1075	   * data may have been sent (if streaming == false), but the playback is
1076	   * not complete until we get the AUDIO_MSG_COMPLETE (or AUDIO_MSG_STOP)
1077	   * message
1078	   *
1079	   * The normal protocol for streaming errors detected by the audio driver
1080	   * is as follows:
1081	   *
1082	   * (1) The audio driver will indicated the error by returning a negated
1083	   *     error value when the next buffer is enqueued.  The upper level
1084	   *     then knows that this buffer was not queue.
1085	   * (2) The audio driver must return all queued buffers using the
1086	   *     AUDIO_MSG_DEQUEUE message, and
1087	   * (3) Terminate playing by sending the AUDIO_MSG_COMPLETE message.
1088	   */
1089	
1090	  audinfo("%s\n", running ? "Playing..." : "Not running");
1091	  while (running)
1092	    {
1093	      /* Wait for a signal either from the Audio driver that it needs
1094	       * additional buffer data, or from a user-space signal to pause,
1095	       * stop, etc.
1096	       */
1097	
1098	      size = mq_receive(pplayer->mq, (FAR char *)&msg, sizeof(msg), &prio);
1099	
1100	      /* Validate a message was received */
1101	
1102	      if (size != sizeof(msg))
1103	        {
1104	          /* Interrupted by a signal? What to do? */
1105	
1106	          continue;
1107	        }
1108	
1109	      /* Perform operation based on message id */
1110	
1111	      switch (msg.msg_id)
1112	        {
1113	          /* An audio buffer is being dequeued by the driver */
1114	
1115	          case AUDIO_MSG_DEQUEUE:
1116	
1117	#ifdef CONFIG_DEBUG_FEATURES
1118	            /* Make sure that we believe that the audio driver has at
1119	             * least one buffer.
1120	             */
1121	
1122	            DEBUGASSERT(msg.u.ptr && outstanding > 0);
1123	            outstanding--;
1124	#endif
1125	
1126	            /* Read data from the file directly into this buffer and
1127	             * re-enqueue it.  streaming == true means that we have
1128	             * not yet hit the end-of-file.
1129	             */
1130	
1131	            if (streaming)
1132	              {
1133	                /* Read the next buffer of data */
1134	
1135	                if (pplayer->tone.sample_rate)
1136	                  {
1137	                    /* Fill the generated tone data into apb  */
1138	
1139	                    ret = nxplayer_filltone(&pplayer->tone, msg.u.ptr);
1140	                  }
1141	                else
1142	                  {
1143	                    /* Fill the audio data of the file into apb */
1144	
1145	                    ret = nxplayer_readbuffer(pplayer, msg.u.ptr);
1146	                  }
1147	
1148	                if (ret != OK)
1149	                  {
1150	                    /* Out of data.  Stay in the loop until the device sends
1151	                     * us a COMPLETE message, but stop trying to play more
1152	                     * data.
1153	                     */
1154	
1155	                    streaming = false;
1156	                  }
1157	
1158	                /* Enqueue buffer by sending it to the audio driver */
1159	
1160	                else
1161	                  {
1162	                    ret = nxplayer_enqueuebuffer(pplayer, msg.u.ptr);
1163	                    if (ret != OK)
1164	                      {
1165	                        /* There is some issue from the audio driver.
1166	                         * Perhaps a problem in the file format?
1167	                         *
1168	                         * We must stop streaming as gracefully as possible.
1169	                         * Close the file so that no further data is read.
1170	                         */
1171	
1172	                        close(pplayer->fd);
1173	                        pplayer->fd = -1;
1174	
1175	                        /* Stop streaming and wait for buffers to be
1176	                         * returned and to receive the AUDIO_MSG_COMPLETE
1177	                         * indication.
1178	                         */
1179	
1180	                        streaming = false;
1181	                        failed = true;
1182	                      }
1183	#ifdef CONFIG_DEBUG_FEATURES
1184	                    else
1185	                      {
1186	                        /* The audio driver has one more buffer */
1187	
1188	                        outstanding++;
1189	                      }
1190	#endif
1191	                  }
1192	              }
1193	            break;
1194	
1195	          /* Someone wants to stop the playback. */
1196	
1197	          case AUDIO_MSG_STOP:
1198	
1199	            /* Send a stop message to the device */
1200	
1201	#ifdef CONFIG_DEBUG_FEATURES
1202	            audinfo("Stopping! outstanding=%d\n", outstanding);
1203	#endif
1204	
1205	#ifdef CONFIG_AUDIO_MULTI_SESSION
1206	            ioctl(pplayer->dev_fd, AUDIOIOC_STOP,
1207	                 (unsigned long)pplayer->session);
1208	#else
1209	            ioctl(pplayer->dev_fd, AUDIOIOC_STOP, 0);
1210	#endif
1211	            /* Stay in the running loop (without sending more data).
1212	             * we will need to recover our audio buffers.  We will
1213	             * loop until AUDIO_MSG_COMPLETE is received.
1214	             */
1215	
1216	            streaming = false;
1217	            break;
1218	
1219	          /* Message indicating the playback is complete */
1220	
1221	          case AUDIO_MSG_COMPLETE:
1222	#ifdef CONFIG_DEBUG_FEATURES
1223	            audinfo("Play complete.  outstanding=%d\n", outstanding);
1224	            DEBUGASSERT(outstanding == 0);
1225	#endif
1226	
1227	#ifdef CONFIG_AUDIO_MULTI_SESSION
1228	            ioctl(pplayer->dev_fd, AUDIOIOC_STOP,
1229	                 (unsigned long)pplayer->session);
1230	#else
1231	            ioctl(pplayer->dev_fd, AUDIOIOC_STOP, 0);
1232	#endif
1233	            running = false;
1234	            break;
1235	
1236	          /* Unknown / unsupported message ID */
1237	
1238	          default:
1239	            break;
1240	        }
1241	    }
1242	
1243	  /* Release our audio buffers and unregister / release the device */
1244	
1245	err_out:
1246	  audinfo("Clean-up and exit\n");
1247	
1248	  if (buffers != NULL)
1249	    {
1250	      audinfo("Freeing buffers\n");
1251	      for (x = 0; x < buf_info.nbuffers; x++)
1252	        {
1253	          /* Fill in the buffer descriptor struct to issue a free request */
1254	
1255	          if (buffers[x] != NULL)
1256	            {
1257	#ifdef CONFIG_AUDIO_MULTI_SESSION
1258	              buf_desc.session = pplayer->session;
1259	#endif
1260	              buf_desc.u.buffer = buffers[x];
1261	              ioctl(pplayer->dev_fd, AUDIOIOC_FREEBUFFER,
1262	                    (unsigned long)&buf_desc);
1263	            }
1264	        }
1265	
1266	      /* Free the pointers to the buffers */
1267	
1268	      free(buffers);
1269	    }
1270	
1271	  /* Unregister the message queue and release the session */
1272	
1273	  ioctl(pplayer->dev_fd, AUDIOIOC_UNREGISTERMQ, (unsigned long)pplayer->mq);
1274	
1275	#ifdef CONFIG_AUDIO_MULTI_SESSION
1276	  ioctl(pplayer->dev_fd, AUDIOIOC_RELEASE, (unsigned long)pplayer->session);
1277	#else
1278	  ioctl(pplayer->dev_fd, AUDIOIOC_RELEASE, 0);
1279	#endif
1280	
1281	  /* Cleanup */
1282	
1283	  pthread_mutex_lock(&pplayer->mutex);
1284	
1285	  /* Close the files */
1286	
1287	  if (0 < pplayer->fd)
1288	    {
1289	      close(pplayer->fd);                 /* Close the file */
1290	      pplayer->fd = -1;                   /* Clear out the FD */
1291	    }
1292	
1293	  close(pplayer->dev_fd);                 /* Close the device */
1294	  pplayer->dev_fd = -1;                   /* Mark device as closed */
1295	  DEBUGVERIFY(mq_close(pplayer->mq));     /* Close the message queue */
1296	  mq_unlink(pplayer->mqname);             /* Unlink the message queue */
1297	  pplayer->ops = NULL;                    /* Clear offload parser */
1298	  pplayer->result = pplayer->stop_requested ? -ECANCELED :
1299	                    failed ? (ret < 0 ? ret : -EIO) : OK;
1300	  pplayer->stop_requested = false;
1301	  pplayer->state = NXPLAYER_STATE_IDLE;   /* Go to IDLE */
1302	
1303	  /* Clear the tone field */
1304	
1305	  memset(&pplayer->tone, 0, sizeof(pplayer->tone));
1306	
1307	  pthread_mutex_unlock(&pplayer->mutex);
1308	
1309	  /* The playthread is done with the context.  Release it, which may
1310	   * actually cause the context to be freed if the creator has already
1311	   * abandoned (released) the context too.
1312	   */
1313	
1314	  nxplayer_release(pplayer);
1315	
1316	  audinfo("Exit\n");
1317	
1318	  return NULL;
1319	}
