1831	/****************************************************************************
1832	 * Name: nxplayer_stop
1833	 *
1834	 *   nxplayer_stop() stops the current playback and closes the file and
1835	 *   the associated device.
1836	 *
1837	 * Input:
1838	 *   pplayer    Pointer to the initialized MPlayer context
1839	 *
1840	 ****************************************************************************/
1841	
1842	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1843	int nxplayer_stop(FAR struct nxplayer_s *pplayer)
1844	{
1845	  struct audio_msg_s term_msg;
1846	  bool active;
1847	
1848	  DEBUGASSERT(pplayer != NULL);
1849	
1850	  /* STARTING is an active lifecycle too.  Record the predicate before
1851	   * notifying the asynchronous thread so it cannot later publish PLAYING.
1852	   */
1853	
1854	  pthread_mutex_lock(&pplayer->mutex);
1855	  active = pplayer->state != NXPLAYER_STATE_IDLE || pplayer->play_id > 0;
1856	  if (active)
1857	    {
1858	      pplayer->stop_requested = true;
1859	      pplayer->state = NXPLAYER_STATE_STOPPING;
1860	      pplayer->result = -EINPROGRESS;
1861	      term_msg.msg_id = AUDIO_MSG_STOP;
1862	      term_msg.u.data = 0;
1863	      mq_send(pplayer->mq, (FAR const char *)&term_msg, sizeof(term_msg),
1864	              CONFIG_NXPLAYER_MSG_PRIO);
1865	    }
1866	
1867	  pthread_mutex_unlock(&pplayer->mutex);
1868	  if (!active)
1869	    {
1870	      return OK;
1871	    }
1872	
1873	  /* Join the thread.  The thread will do all the cleanup. */
1874	
1875	  nxplayer_jointhread(pplayer);
1876	  return OK;
1877	}
1878	#endif /* CONFIG_AUDIO_EXCLUDE_STOP */
