1880	int nxplayer_getstatus(FAR struct nxplayer_s *pplayer,
1881	                       FAR struct nxplayer_status_s *status)
1882	{
1883	  if (pplayer == NULL || status == NULL)
1884	    {
1885	      return -EINVAL;
1886	    }
1887	
1888	  pthread_mutex_lock(&pplayer->mutex);
1889	  status->state = pplayer->state;
1890	  status->result = pplayer->result;
1891	  pthread_mutex_unlock(&pplayer->mutex);
1892	  return OK;
1893	}
