1895	/****************************************************************************
1896	 * Name: nxplayer_playinternal
1897	 *
1898	 *   nxplayer_playinternal() tries to play the specified file/raw data
1899	 *   using the Audio system.  If a preferred device is specified, it will
1900	 *   try to use that device otherwise it will perform a search of the Audio
1901	 *   device files to find a suitable device.
1902	 *
1903	 * Input:
1904	 *   pplayer    Pointer to the initialized MPlayer context
1905	 *   filefmt    Format of the file or AUD_FMT_UNDEF if unknown / to be
1906	 *              determined by nxplayer_playfile()
1907	 *   subfmt     Sub-Format of the file or AUD_FMT_UNDEF if unknown / to be
1908	 *              determined by nxplayer_playfile()
1909	 *   nchannels  channels num (raw data playback needed)
1910	 *   bpsamp     bits pre sample (raw data playback needed)
1911	 *   samprate  samplre rate (raw data playback needed)
1912	 *   chmap      channel map (raw data playback needed)
1913	 *
1914	 * Returns:
1915	 *   OK         File is being played
1916	 *   -EBUSY     The media device is busy
1917	 *   -ENOSYS    The media file is an unsupported type
1918	 *   -ENODEV    No audio device suitable to play the media type
1919	 *   -ENOENT    The media file was not found
1920	 *
1921	 *
1922	 ****************************************************************************/
1923	
1924	static int nxplayer_playinternal(FAR struct nxplayer_s *pplayer,
1925	                                 int filefmt, int subfmt,
1926	                                 uint8_t nchannels, uint8_t bpsamp,
1927	                                 uint32_t samprate, uint8_t chmap)
1928	{
1929	  struct mq_attr      attr;
1930	  struct sched_param  sparam;
1931	  pthread_attr_t      tattr;
1932	  struct audio_caps_desc_s cap_desc;
1933	  struct ap_buffer_info_s  buf_info;
1934	  struct audio_caps_s      caps;
1935	  int                      min_channels;
1936	  int                 ret;
1937	
1938	  /* Try to open the device */
1939	
1940	  ret = nxplayer_opendevice(pplayer, filefmt, subfmt);
1941	  if (ret < 0)
1942	    {
1943	      /* Error opening the device */
1944	
1945	      auderr("ERROR: nxplayer_opendevice failed: %d\n", ret);
1946	      return ret;
1947	    }
1948	
1949	  /* Try to reserve the device */
1950	
1951	#ifdef CONFIG_AUDIO_MULTI_SESSION
1952	  ret = ioctl(pplayer->dev_fd, AUDIOIOC_RESERVE,
1953	              (unsigned long)&pplayer->session);
1954	#else
1955	  ret = ioctl(pplayer->dev_fd, AUDIOIOC_RESERVE, 0);
1956	#endif
1957	  if (ret < 0)
1958	    {
1959	      /* Device is busy or error */
1960	
1961	      auderr("ERROR: Failed to reserve device: %d\n", ret);
1962	      ret = -errno;
1963	      goto err_out;
1964	    }
1965	
1966	  caps.ac_len = sizeof(caps);
1967	  caps.ac_type = AUDIO_TYPE_OUTPUT;
1968	  caps.ac_subtype = AUDIO_TYPE_QUERY;
1969	
1970	  if (ioctl(pplayer->dev_fd, AUDIOIOC_GETCAPS,
1971	      (unsigned long)&caps) == caps.ac_len)
1972	    {
1973	      min_channels = caps.ac_channels >> 4;
1974	
1975	      if (min_channels != 0 && nchannels < min_channels)
1976	        {
1977	          ret = -EINVAL;
1978	          goto err_out;
1979	        }
1980	    }
1981	
1982	  if (nchannels && samprate && bpsamp)
1983	    {
1984	#ifdef CONFIG_AUDIO_MULTI_SESSION
1985	      cap_desc.session = pplayer->session;
1986	#endif
1987	      cap_desc.caps.ac_len            = sizeof(struct audio_caps_s);
1988	      cap_desc.caps.ac_type           = AUDIO_TYPE_OUTPUT;
1989	      cap_desc.caps.ac_channels       = nchannels;
1990	      cap_desc.caps.ac_chmap          = chmap;
1991	      cap_desc.caps.ac_controls.hw[0] = samprate;
1992	      cap_desc.caps.ac_controls.b[3]  = samprate >> 16;
1993	      cap_desc.caps.ac_controls.b[2]  = bpsamp;
1994	      cap_desc.caps.ac_subtype        = filefmt;
1995	
1996	      ioctl(pplayer->dev_fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap_desc);
1997	    }
1998	
1999	  /* Query the audio device for its preferred buffer count */
2000	
2001	  if (ioctl(pplayer->dev_fd, AUDIOIOC_GETBUFFERINFO,
2002	            (unsigned long)&buf_info) != OK)
2003	    {
2004	      /* Driver doesn't report its buffer size.  Use our default. */
2005	
2006	      buf_info.nbuffers = CONFIG_AUDIO_NUM_BUFFERS;
2007	    }
2008	
2009	  /* Create a message queue for the playthread */
2010	
2011	  attr.mq_maxmsg  = buf_info.nbuffers + 8;
2012	  attr.mq_msgsize = sizeof(struct audio_msg_s);
2013	  attr.mq_curmsgs = 0;
2014	  attr.mq_flags   = 0;
2015	
2016	  snprintf(pplayer->mqname, sizeof(pplayer->mqname), "/tmp/%0lx",
2017	           (unsigned long)((uintptr_t)pplayer));
2018	
2019	  pplayer->mq = mq_open(pplayer->mqname, O_RDWR | O_CREAT, 0644, &attr);
2020	  if (pplayer->mq == (mqd_t) -1)
2021	    {
2022	      /* Unable to open message queue! */
2023	
2024	      ret = -errno;
2025	      auderr("ERROR: mq_open failed: %d\n", ret);
2026	      goto err_out;
2027	    }
2028	
2029	  /* Register our message queue with the audio device */
2030	
2031	  ioctl(pplayer->dev_fd, AUDIOIOC_REGISTERMQ, (unsigned long)pplayer->mq);
2032	
2033	  /* Check if there was a previous thread and join it if there was
2034	   * to perform clean-up.
2035	   */
2036	
2037	  nxplayer_jointhread(pplayer);
2038	
2039	  /* Start the playfile thread to stream the media file to the
2040	   * audio device.  Publish STARTING before the asynchronous thread can be
2041	   * observed by callers so IDLE always means a terminal lifecycle.
2042	   */
2043	
2044	  pthread_mutex_lock(&pplayer->mutex);
2045	  pplayer->state = NXPLAYER_STATE_STARTING;
2046	  pplayer->result = -EINPROGRESS;
2047	  pplayer->stop_requested = false;
2048	  pthread_mutex_unlock(&pplayer->mutex);
2049	
2050	  ret = pthread_attr_init(&tattr);
2051	  if (ret != OK)
2052	    {
2053	      auderr("ERROR: Failed to init playthread: %d\n", ret);
2054	      goto err_out;
2055	    }
2056	
2057	  sparam.sched_priority = sched_get_priority_max(SCHED_FIFO) - 9;
2058	  pthread_attr_setschedparam(&tattr, &sparam);
2059	  pthread_attr_setstacksize(&tattr,
2060	                            CONFIG_NXPLAYER_PLAYTHREAD_STACKSIZE);
2061	
2062	  /* Add a reference count to the player for the thread and start the
2063	   * thread.  We increment for the thread to avoid thread start-up
2064	   * race conditions.
2065	   */
2066	
2067	  nxplayer_reference(pplayer);
2068	  ret = pthread_create(&pplayer->play_id, &tattr, nxplayer_playthread,
2069	                       (pthread_addr_t) pplayer);
2070	  pthread_attr_destroy(&tattr);
2071	  if (ret != OK)
2072	    {
2073	      auderr("ERROR: Failed to create playthread: %d\n", ret);
2074	      goto err_out;
2075	    }
2076	
2077	  /* Name the thread */
2078	
2079	  pthread_setname_np(pplayer->play_id, "playthread");
2080	  return OK;
2081	
2082	err_out:
2083	  close(pplayer->dev_fd);
2084	  pplayer->dev_fd = -1;
2085	  nxplayer_setstate(pplayer, NXPLAYER_STATE_IDLE, ret);
2086	
2087	  return ret;
2088	}
