2435	/****************************************************************************
2436	 * Name: nxplayer_release
2437	 *
2438	 *   nxplayer_release() reduces the reference count by one and if it
2439	 *   reaches zero, frees the context.
2440	 *
2441	 * Input Parameters:
2442	 *   pplayer    Pointer to the NxPlayer context
2443	 *
2444	 * Returned values:    None
2445	 *
2446	 ****************************************************************************/
2447	
2448	void nxplayer_release(FAR struct nxplayer_s *pplayer)
2449	{
2450	  int         refcount;
2451	
2452	  /* Check if there was a previous thread and join it if there was */
2453	
2454	  nxplayer_jointhread(pplayer);
2455	
2456	  pthread_mutex_lock(&pplayer->mutex);
2457	
2458	  /* Reduce the reference count */
2459	
2460	  refcount = pplayer->crefs--;
2461	  pthread_mutex_unlock(&pplayer->mutex);
2462	
2463	  /* If the ref count *was* one, then free the context */
2464	
2465	  if (refcount == 1)
2466	    {
2467	      free(pplayer);
2468	    }
2469	}
2470	
2471	/****************************************************************************
2472	 * Name: nxplayer_reference
2473	 *
2474	 *   nxplayer_reference() increments the reference count by one.
2475	 *
2476	 * Input Parameters:
2477	 *   pplayer    Pointer to the NxPlayer context
2478	 *
2479	 * Returned values:    None
2480	 *
2481	 ****************************************************************************/
2482	
2483	void nxplayer_reference(FAR struct nxplayer_s *pplayer)
2484	{
2485	  pthread_mutex_lock(&pplayer->mutex);
2486	
2487	  /* Increment the reference count */
2488	
2489	  pplayer->crefs++;
2490	  pthread_mutex_unlock(&pplayer->mutex);
2491	}
