873			{
874				syslog(LOG_ERR, "channel %d\n", priv->nchannels);
875				ret = -EINVAL;
876				return ret;
877			}
878		}
879	
880	#endif
881	
882		pthread_mutex_init(&priv->mutex, NULL);
