888		syslog(LOG_INFO,"Starting worker thread\n");
889	
890		if (priv->record)
891			priv->task = audio_thread_create(&priv->sem, record_workerthread, priv, "sunxi-audio-1",
892								stack_size, (sched_get_priority_max(SCHED_FIFO) - 3));
893		else
894			priv->task = audio_thread_create(&priv->sem, play_workerthread, priv, "sunxi-audio-0",
895								stack_size, (sched_get_priority_max(SCHED_FIFO) - 3));
896		if (!priv->task)
897		{
898			syslog(LOG_ERR, "ERROR: pthread_create failed: %d\n", ret);
899		}
900		else
901		{
902			hal_thread_start(priv->task);
903			syslog(LOG_INFO,"Created worker thread\n");
904		}
