906		ret = nxsem_tickwait_uninterruptible(&priv->start_handle, MS_TO_OSTICK(1000));
907		if (ret != OK) {
908			syslog(LOG_ERR, "wait bind start_handle timeout!\n");
909			return ret;
910		}
911	
