916	/****************************************************************************
917	 * Name: sunxi_audio_stop
918	 *
919	 * Description:
920	 *   Stop the configured operation (audio streaming, volume disabled, etc.).
921	 *
922	 ****************************************************************************/
923	
924	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
925	#  ifdef CONFIG_AUDIO_MULTI_SESSION
926	static int sunxi_audio_stop(FAR struct audio_lowerhalf_s *dev, FAR void *session)
927	#  else
928	static int sunxi_audio_stop(FAR struct audio_lowerhalf_s *dev)
929	#  endif
930	{
931		FAR struct sunxi_dev_s *priv = (FAR struct sunxi_dev_s *)dev;
932		struct audio_msg_s term_msg;
933		int ret = 0;
934		unsigned int prio;
935		syslog(LOG_INFO, "%d, %s\n", __LINE__, __func__);
936	
937		if (priv->index == AW_AUDIO_CODEC)
938			prio = CONFIG_AW_AUDIO_CODEC_MSG_PRIO;
939		else if (priv->index == AW_AUDIO_DMIC)
940			prio = CONFIG_AW_AUDIO_DMIC_MSG_PRIO;
941		else {
942			ret = -EINVAL;
943			syslog(LOG_ERR, "index: %d err\n", priv->index);
944			return ret;
945		}
946	
947		/* Send a message to stop all audio streaming */
948		term_msg.msg_id = AUDIO_MSG_STOP;
949		term_msg.u.data = 0;
950		priv->running = false;
951		//priv->paused = false;
952	
953		pthread_cond_signal(&priv->cond_pause);
954		file_mq_send(&priv->mq, (FAR const char *)&term_msg, sizeof(term_msg),
955					prio);
956	
957	#if (defined CONFIG_AW_AUDIO_RPMSG_CTRL)
958		if (priv->record)
959		{
960			rpmsg_audio_ctrl_t audio_rpmsg_ctrl_param;
961			memset(&audio_rpmsg_ctrl_param, 0 , sizeof(rpmsg_audio_ctrl_t));
962			audio_rpmsg_ctrl_param.cmd = RPMSG_CTL_STOP;
963			ret = audio_rpmsg_ctl_send_cmd(RPMSG_DIR_NAME, &audio_rpmsg_ctrl_param);
964			if (ret != 0)
965			{
966				syslog(LOG_ERR, "rpmsg send err\n");
967				return ret;
968			}
969		}
970	#endif
971	
972		if (priv->handle != NULL) {
973			if (priv->paused) {
974				ret = snd_vela_pcm_reset(priv->handle);
975				if (ret < 0)
976					syslog(LOG_ERR, "%d, reset failed!, return %d\n", __LINE__, ret);
977			}
978			priv->paused = false;
979	
980			if (!priv->record && !priv->natural_complete) {
981				ret = snd_vela_pcm_drop(priv->handle);
982			} else {
983				ret = snd_vela_pcm_drain(priv->handle);
984			}
985			if (ret < 0)
986			{
987				syslog(LOG_ERR, "stop failed!, return %d\n", ret);
988			}
989	
990			audio_thread_stop(&priv->sem, priv->task);
991			/* close card */
992			ret = snd_vela_pcm_close(priv->handle);
993			if (ret < 0)
994			{
995				syslog(LOG_ERR, "audio close error:%d\n", ret);
996				return ret;
997			}
998			priv->handle = NULL;
999		} else {
1000			audio_thread_stop(&priv->sem, priv->task);
1001		}
1002	
1003		pthread_mutex_destroy(&priv->mutex);
1004		pthread_cond_destroy(&priv->cond_pause);
1005		sem_destroy(&priv->start_handle);
1006	
1007		/* REVISIT: */
1008		return OK;
1009	}
1010	#endif
