1273	/****************************************************************************
1274	 * Name: record_workerthread
1275	 *
1276	 *  This is the thread that gets data from the chip and keeps the audio
1277	 *  stream going.
1278	 *
1279	 ****************************************************************************/
1280	
1281	static void record_workerthread(void *arg)
1282	{
1283		FAR struct sunxi_dev_s *priv = (struct sunxi_dev_s *)arg;
1284		struct audio_msg_s msg;
1285		FAR struct ap_buffer_s *apb;
1286		int msglen;
1287		unsigned int prio;
1288	
1289		syslog(LOG_INFO,"Entry\n");
1290	
1291	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1292		priv->terminating = false;
1293	#endif
1294	
1295	/* Mark ourself as running */
1296		priv->running = true;
1297		memset(&msg, 0, sizeof(msg));
1298	
1299	#if (!defined CONFIG_AW_AUDIO_RPMSG_CTRL)
1300	
1301		int direction, ret;
1302	
1303		direction = priv->record ? SND_VELA_PCM_STREAM_CAPTURE
1304									: SND_VELA_PCM_STREAM_PLAYBACK;
1305	
1306		/* open card */
1307		ret = snd_vela_pcm_open(&priv->handle, priv->pcm_name, direction, 0);
1308		if (ret < 0)
1309		{
1310			syslog(LOG_ERR, "audio open error:%d\n", ret);
1311			return;
1312		}
1313	
1314		ret = set_param(priv->handle, priv->format, priv->samprate, priv->nchannels,
1315				priv->period_size, priv->buffer_size);
1316		if (ret < 0)
1317		{
1318			syslog(LOG_ERR, "set_param error:%d\n", ret);
1319			priv->running = false;
1320		}
1321		sem_post(&priv->start_handle);
1322	
1323	#endif
1324		/* Loop as long as we are supposed to be running and as long as we have
1325		* buffers in-flight.
1326		*/
1327		record_fillbuffer(priv);
1328	
1329		while (priv->running)
1330		{
1331			/* Check if we have been asked to terminate.  We have to check if we
1332			* still have buffers in-flight.  If we do, then we can't stop until
1333			* birds come back to roost.
1334			*/
1335	
1336			if (priv->terminating)
1337			{
1338				/* We are IDLE.  Break out of the loop and exit. */
1339	
1340				break;
1341			}
1342	
1343			if (priv->paused)
1344			{
1345				/* We are pause.. */
1346				pthread_mutex_lock(&priv->mutex);
1347				pthread_cond_wait(&priv->cond_pause, &priv->mutex);
1348				pthread_mutex_unlock(&priv->mutex);
1349				if (!priv->running)
1350					break;
1351			}
1352	
1353			/* Wait for messages from our message queue */
1354	
1355			msglen = file_mq_receive(&priv->mq, (FAR char *)&msg,
1356									sizeof(msg), &prio);
1357	
1358			/* Handle the case when we return with no message */
1359	
1360			if (msglen < sizeof(struct audio_msg_s))
1361			{
1362				syslog(LOG_ERR, "ERROR: Message too small: %d\n", msglen);
1363				continue;
1364			}
1365	
1366			/* Process the message */
1367	
1368			switch (msg.msg_id)
1369			{
1370				/* Stop the playback */
1371	
1372	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1373				case AUDIO_MSG_STOP:
1374	
1375				/* Indicate that we are terminating */
1376	
1377				syslog(LOG_INFO,"AUDIO_MSG_STOP: Terminating\n");
1378				priv->terminating = true;
1379				break;
1380	#endif
1381	
1382				/* We have a new buffer to fill.  We will catch this case at
1383				* the top of the loop.
1384				*/
1385	
1386				case AUDIO_MSG_ENQUEUE:
1387				audinfo("AUDIO_MSG_ENQUEUE\n");
1388				record_fillonebuffer(priv);
1389				break;
1390	
1391				case AUDIO_MSG_COMPLETE:
1392				syslog(LOG_INFO,"AUDIO_MSG_COMPLETE\n");
1393				break;
1394	
1395				default:
1396				syslog(LOG_ERR, "ERROR: Ignoring message ID %d\n", msg.msg_id);
1397				break;
1398			}
1399		}
1400	
1401		/* Reset the audio param */
1402	
1403		sunxi_audio_reset(priv);
1404	
1405		/* Return any pending buffers in our pending queue */
1406	
1407		nxmutex_lock(&priv->pendlock);
1408		while ((apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq)) != NULL)
1409		{
1410	
1411			/* Send the buffer back up to the previous level. */
1412	
1413	#ifdef CONFIG_AUDIO_MULTI_SESSION
1414			priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, OK, NULL);
1415	#else
1416			priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, OK);
1417	#endif
1418		}
1419	
1420		nxmutex_unlock(&priv->pendlock);
1421	
1422		/* Close the message queue */
1423	
1424		file_mq_close(&priv->mq);
1425		file_mq_unlink(priv->mqname);
1426	
1427		/* Send an AUDIO_MSG_COMPLETE message to the client */
1428	
1429	#ifdef CONFIG_AUDIO_MULTI_SESSION
1430		priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, NULL);
1431	#else
1432		priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
1433	#endif
1434	
1435		syslog(LOG_INFO, "A7 record exit\n");
1436		sem_post(&priv->sem);
1437	}
