1439	/****************************************************************************
1440	 * Name: play_workerthread
1441	 *
1442	 *  This is the thread that write data to the chip and keeps the playback
1443	 *  stream going.
1444	 *
1445	 ****************************************************************************/
1446	
1447	static void play_workerthread(void *arg)
1448	{
1449		FAR struct sunxi_dev_s *priv = (struct sunxi_dev_s *)arg;
1450		struct audio_msg_s msg;
1451		struct ap_buffer_s *apb;
1452		unsigned int prio;
1453		bool final;
1454		int ret, msglen;
1455		void *equalizer = NULL;
1456	
1457		snd_pcm_sframes_t samples;
1458		snd_pcm_uframes_t frames = 0;
1459		int direction;
1460	
1461	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1462		priv->terminating = false;
1463	#endif
1464		priv->running = true;
1465		priv->natural_complete = false;
1466		memset(&msg, 0, sizeof(msg));
1467	
1468		direction = priv->record ? SND_VELA_PCM_STREAM_CAPTURE
1469									: SND_VELA_PCM_STREAM_PLAYBACK;
1470	
1471		/* open card */
1472		ret = snd_vela_pcm_open(&priv->handle, priv->pcm_name, direction, 0);
1473		if (ret < 0)
1474		{
1475			syslog(LOG_ERR, "audio open error:%d\n", ret);
1476			return;
1477		}
1478	
1479		syslog(LOG_INFO,"%s:set param format:%d rate:%d ch:%d period_size:%ld buffer_size:%ld\n", __func__, priv->format,
1480						priv->samprate, priv->nchannels,priv->period_size, priv->buffer_size);
1481	
1482		ret = set_param(priv->handle, priv->format, priv->samprate, priv->nchannels,
1483				priv->period_size / 4, priv->buffer_size / 4);
1484		if (ret < 0)
1485		{
1486			syslog(LOG_ERR, "set_param error:%d\n", ret);
1487			priv->running = false;
1488		}
1489	
1490		ret = snd_vela_pcm_prepare(priv->handle);
1491		if (ret < 0) {
1492			syslog(LOG_INFO, "prepare failed. return %d\n", ret);
1493		}
1494		sem_post(&priv->start_handle);
1495	
1496		if (priv->eq_enable) {
1497			syslog(LOG_INFO, "eq_create\n");
1498			equalizer = eq_create(&priv->eqprms);
1499			if (equalizer == NULL)
1500				syslog(LOG_ERR, "create equalizer handle error!\n");
1501			deinit_eq_prms(&priv->eqprms);
1502		}
1503	
1504		while (priv->running) {
1505			apb = (struct ap_buffer_s *)dq_peek(&priv->pendq);
1506			if (!apb) {
1507				usleep(5000);
1508				continue;
1509			}
1510			frames = apb->nbytes / (priv->bpsamp / 8 * priv->nchannels);
1511			final = (apb->flags & AUDIO_APB_FINAL) != 0;
1512	
1513			start_before++;
1514			if (priv->eq_enable && equalizer)
1515				eq_process(equalizer, (short*)apb->samp, frames);
1516	
1517			samples = snd_vela_pcm_writei(priv->handle, apb->samp, frames);
1518			if (samples != frames) {
1519				syslog(LOG_INFO, "snd_vela_pcm_writei return %ld\n", samples);
1520				if (!priv->handle) {
1521					syslog(LOG_INFO, "handle is null\n");
1522					usleep(5000);
1523					continue;
1524				}
1525			}
1526			if (samples == -EAGAIN) {
1527				usleep(10000);
1528				continue;
1529			} else if (samples == -EPIPE) {
1530				if (!priv->running) {
1531					syslog(LOG_INFO, "%d, receive the stop cmd\n", __LINE__);
1532					break;
1533				}
1534				xrun(priv->handle);
1535				continue;
1536			} else if (samples == -ESTRPIPE) {
1537				continue;
1538			} else if ((samples < 0) && (priv->running)) {
1539				syslog(LOG_INFO, "-----snd_vela_pcm_writei failed!!, return %ld\n", samples);
1540				ret = snd_vela_pcm_prepare(priv->handle);
1541				if (ret < 0) {
1542					syslog(LOG_INFO, "prepare failed in write. return %d\n", ret);
1543				}
1544				continue;
1545			} else if ((samples < 0) && (!priv->running)) {
1546				syslog(LOG_INFO, "%d, receive the stop cmd\n", __LINE__);
1547				break;
1548			}
1549	
1550			nxmutex_lock(&priv->pendlock);
1551			dq_remfirst(&priv->pendq);
1552			nxmutex_unlock(&priv->pendlock);
1553	
1554			dq_before++;
1555			priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, OK);
1556			dq_after++;
1557	
1558			if (final) {
1559				syslog(LOG_INFO, "playback final buffer complete\n");
1560				priv->natural_complete = true;
1561				priv->running = false;
1562				break;
1563			}
1564	
1565			msglen = file_mq_receive(&priv->mq, (FAR char *)&msg,
1566									sizeof(msg), &prio);
1567	
1568			/* The queue is non-blocking, so no message is the normal case. */
1569	
1570			if (msglen < 0) {
1571				if (msglen != -EAGAIN)
1572					syslog(LOG_ERR, "ERROR: file_mq_receive failed: %d\n", msglen);
1573				continue;
1574			}
1575	
1576			if (msglen != sizeof(struct audio_msg_s)) {
1577				syslog(LOG_ERR, "ERROR: Message too small: %d\n", msglen);
1578				continue;
1579			}
1580	
1581			switch (msg.msg_id)
1582			{
1583				case AUDIO_MSG_ENQUEUE:
1584				audinfo("AUDIO_MSG_ENQUEUE\n");
1585				break;
1586				/* Stop the playback */
1587	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1588				case AUDIO_MSG_STOP:
1589				/* Indicate that we are terminating */
1590	
1591				syslog(LOG_INFO,"AUDIO_MSG_STOP: Terminating\n");
1592				priv->terminating = true;
1593				break;
1594	#endif
1595				/* We have a new buffer to fill.  We will catch this case at
1596				* the top of the loop.
1597				*/
1598	
1599				case AUDIO_MSG_COMPLETE:
1600				syslog(LOG_INFO,"AUDIO_MSG_COMPLETE\n");
1601				break;
1602	
1603				default:
1604				syslog(LOG_ERR, "ERROR: Ignoring message ID %d\n", msg.msg_id);
1605				break;
1606			}
1607			if (priv->terminating == true)
1608				break;
1609		}
1610	
1611		if (priv->eq_enable && equalizer) {
1612			syslog(LOG_INFO, "eq_destroy\n");
1613			eq_destroy(equalizer);
1614			equalizer = NULL;
1615		}
1616	
1617		nxmutex_lock(&priv->pendlock);
1618		while ((apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq)) != NULL)
1619		{
1620	
1621			/* Send the buffer back up to the previous level. */
1622	
1623	#ifdef CONFIG_AUDIO_MULTI_SESSION
1624			priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, OK, NULL);
1625	#else
1626			priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, OK);
1627	#endif
1628		}
1629		nxmutex_unlock(&priv->pendlock);
1630	
1631		/* Close the message queue */
1632		file_mq_close(&priv->mq);
1633		file_mq_unlink(priv->mqname);
1634	
1635	  /* Send an AUDIO_MSG_COMPLETE message to the client */
1636	#ifdef CONFIG_AUDIO_MULTI_SESSION
1637		priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, NULL);
1638	#else
1639		priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
1640	#endif
1641	
1642		syslog(LOG_INFO, "playback exit\n");
1643		sem_post(&priv->sem);
1644	}
