1332	#ifndef CONFIG_AUDIO_EXCLUDE_VOLUME
1333	int nxplayer_setvolume(FAR struct nxplayer_s *pplayer, uint16_t volume)
1334	{
1335	  struct audio_caps_desc_s  cap_desc;
1336	  int ret;
1337	
1338	  pthread_mutex_lock(&pplayer->mutex);
1339	
1340	  /* If we are currently playing, then we need to post a message to
1341	   * the playthread to perform the volume change operation.  If we
1342	   * are not playing, then just store the volume setting and it will
1343	   * be applied before the next playback begins.
1344	   */
1345	
1346	  if (pplayer->state == NXPLAYER_STATE_PLAYING)
1347	    {
1348	      /* Send a CONFIGURE ioctl to the device to set the volume */
1349	
1350	#ifdef CONFIG_AUDIO_MULTI_SESSION
1351	      cap_desc.session                = pplayer->session;
1352	#endif
1353	      cap_desc.caps.ac_len            = sizeof(struct audio_caps_s);
1354	      cap_desc.caps.ac_type           = AUDIO_TYPE_FEATURE;
1355	      cap_desc.caps.ac_format.hw      = AUDIO_FU_VOLUME;
1356	      cap_desc.caps.ac_controls.hw[0] = volume;
1357	      ret = ioctl(pplayer->dev_fd, AUDIOIOC_CONFIGURE,
1358	                  (unsigned long)&cap_desc);
1359	      if (ret < 0)
1360	        {
1361	          int errcode = errno;
1362	          DEBUGASSERT(errcode > 0);
1363	
1364	          auderr("ERROR: AUDIOIOC_CONFIGURE ioctl failed: %d\n", errcode);
1365	          pthread_mutex_unlock(&pplayer->mutex);
1366	          return -errcode;
1367	        }
1368	    }
1369	
1370	  /* Store the volume setting */
1371	
1372	  pplayer->volume = volume;
1373	  pthread_mutex_unlock(&pplayer->mutex);
1374	
1375	  return OK;
1376	}
