357	static void routine_dispatch_due(struct routine_app_s *app)
358	{
359	  struct routine_due_event_s event;
360	
361	  while (routine_model_take_due(&app->model, &event) == OK)
362	    {
363	      int ui_ret = routine_ui_enqueue_due(&event);
364	
365	      if (ui_ret < 0 && ui_ret != -EALREADY)
366	        {
367	          syslog(LOG_ERR,
368	                 "routine_mgr: due UI queue id=%u failed: %d\n",
369	                 event.schedule_id, ui_ret);
370	        }
371	
372	#ifdef CONFIG_ROUTINE_MANAGER_VOICE
373	      if (app->audio_started)
374	        {
375	          struct audio_service_reminder_s reminder;
376	          int audio_ret;
377	
378	          reminder.sequence = event.sequence;
379	          reminder.schedule_id = event.schedule_id;
380	          reminder.text_id = event.text_id;
381	          reminder.hour = event.hour;
382	          reminder.minute = event.minute;
383	          audio_ret = audio_service_enqueue_reminder(&app->audio, &reminder);
384	          if (audio_ret < 0 && audio_ret != -EALREADY)
385	            {
386	              syslog(LOG_ERR,
387	                     "routine_mgr: due audio queue id=%u failed: %d\n",
388	                     event.schedule_id, audio_ret);
389	            }
390	        }
391	#endif
392	    }
393	}
