395	static void routine_timer_cb(lv_timer_t *timer)
396	{
397	  struct routine_app_s *app = lv_timer_get_user_data(timer);
398	  struct environment_sample_s environment;
399	  struct routine_clock_s clock;
400	
401	  if (app->model.clock_mode == ROUTINE_CLOCK_DEMO)
402	    {
403	      routine_model_tick_demo(&app->model);
404	    }
405	  else if (routine_get_local_clock(&clock) == OK)
406	    {
407	      time_t wall_time = time(NULL);
408	      int clock_ret;
409	
410	      if (app->last_wall_time != 0 &&
411	          (wall_time < app->last_wall_time ||
412	           wall_time - app->last_wall_time > ROUTINE_CLOCK_REBASE_SECONDS))
