619	int routine_ui_enqueue_due(const struct routine_due_event_s *event)
620	{
621	  uint8_t tail;
622	  uint8_t i;
623	
624	  if (event == NULL || event->sequence == 0 ||
625	      event->schedule_id >= ROUTINE_SCHEDULE_MAX)
626	    {
627	      return -EINVAL;
628	    }
629	
630	  for (i = 0; i < g_ui.due_count; i++)
631	    {
632	      uint8_t index = (g_ui.due_head + i) % ROUTINE_DUE_UI_QUEUE_MAX;
633	      if (routine_due_equal(&g_ui.due_queue[index], event))
634	        {
635	          return -EALREADY;
636	        }
637	    }
638	
639	  if (g_ui.dialog_is_due && routine_due_equal(&g_ui.active_due, event))
640	    {
641	      return -EALREADY;
642	    }
643	
644	  if (g_ui.due_count >= ROUTINE_DUE_UI_QUEUE_MAX)
645	    {
646	      return -ENOSPC;
647	    }
648	
649	  tail = (g_ui.due_head + g_ui.due_count) % ROUTINE_DUE_UI_QUEUE_MAX;
650	  g_ui.due_queue[tail] = *event;
651	  g_ui.due_count++;
652	  routine_try_open_due();
653	  return OK;
654	}
