656	void routine_ui_remove_due(const struct routine_due_event_s *event)
657	{
658	  struct routine_due_event_s queue[ROUTINE_DUE_UI_QUEUE_MAX];
659	  uint8_t kept = 0;
660	  uint8_t i;
661	
662	  if (event == NULL || event->sequence == 0)
663	    {
664	      return;
665	    }
666	
667	  for (i = 0; i < g_ui.due_count; i++)
668	    {
669	      uint8_t index = (g_ui.due_head + i) % ROUTINE_DUE_UI_QUEUE_MAX;
670	      if (!routine_due_equal(&g_ui.due_queue[index], event))
671	        {
672	          queue[kept++] = g_ui.due_queue[index];
673	        }
674	    }
675	
676	  memset(g_ui.due_queue, 0, sizeof(g_ui.due_queue));
677	  memcpy(g_ui.due_queue, queue, kept * sizeof(queue[0]));
678	  g_ui.due_head = 0;
679	  g_ui.due_count = kept;
680	}
