608	static int audio_start(FAR struct file *filep, FAR void *session)
609	#else
610	static int audio_start(FAR struct file *filep)
611	#endif
612	{
613	  FAR struct inode *inode = filep->f_inode;
614	  FAR struct audio_upperhalf_s *upper = inode->i_private;
615	  FAR struct audio_lowerhalf_s *lower = upper->dev;
616	  FAR struct audio_openpriv_s *priv = filep->f_priv;
617	  int ret;
618	
619	  DEBUGASSERT(upper != NULL && lower->ops->start != NULL);
620	
621	  if (upper->status->state == AUDIO_STATE_OPEN)
622	    {
623	      return -EPERM;
624	    }
625	  else if (upper->status->state == AUDIO_STATE_PAUSED)
626	    {
627	      audinfo("resume: status=%d\n", upper->status->state);
628	      return audio_resume(filep);
629	    }
630	
631	  /* Verify that the Audio is not already running */
632	
633	  if (upper->status->state == AUDIO_STATE_PREPARED ||
634	      upper->status->state == AUDIO_STATE_XRUN)
635	    {
636	      /* Invoke the bottom half method to start the audio stream */
637	
638	      audinfo("start: status=%d\n", upper->status->state);
639	
640	#ifdef CONFIG_AUDIO_MULTI_SESSION
641	      ret = lower->ops->start(lower, session);
642	#else
643	      ret = lower->ops->start(lower);
644	#endif
645	      /* A return value of zero means that the audio stream was running
646	       * successfully.
647	       */
648	
649	      if (ret != OK)
650	        {
651	          return ret;
652	        }
653	
654	      audio_setstate(upper, AUDIO_STATE_RUNNING);
655	    }
656	
657	  priv->state = AUDIO_STATE_RUNNING;
658	  return OK;
659	}
