388	/****************************************************************************
389	 * Name: audio_try_enqueue
390	 *
391	 * Description:
392	 *   Try enqueue audio buffer
393	 *
394	 ****************************************************************************/
395	
396	static int audio_try_enqueue(FAR struct audio_upperhalf_s *upper)
397	{
398	  FAR struct audio_lowerhalf_s *lower = upper->dev;
399	  FAR struct audio_openpriv_s *priv;
400	  int ret = OK;
401	
402	  for (; ; )
403	    {
404	      uint32_t count = upper->status->head - upper->status->tail;
405	      bool ready = false;
406	      bool wait = false;
407	
408	      for (priv = upper->head; priv != NULL; priv = priv->flink)
409	        {
410	          if (priv->state == AUDIO_STATE_OPEN ||
411	              priv->state == AUDIO_STATE_PAUSED)
412	            {
413	              continue;
414	            }
415	          else if (priv->head > upper->status->head)
416	            {
417	              ready = true;
418	            }
419	          else if (priv->head < upper->status->head ||
420	                   priv->head <= upper->status->tail)
421	            {
422	              priv->state = AUDIO_STATE_XRUN;
423	            }
424	          else
425	            {
426	              wait = true;
427	            }
428	        }
429	
430	      if (!ready || (wait && count > AUDIO_ENQUEUE_THRESHOLD))
431	        {
432	          return OK;
433	        }
434	
435	      if (upper->info.type == AUDIO_TYPE_OUTPUT && upper->dump)
436	        {
437	          file_write(
438	              &upper->file,
439	              upper->apbs[upper->status->head % upper->periods]->samp,
440	              upper->apbs[upper->status->head % upper->periods]->nbytes);
441	        }
442	
443	      ret = lower->ops->enqueuebuffer(
444	          lower, upper->apbs[upper->status->head % upper->periods]);
445	      if (ret < 0)
446	        {
447	          return ret;
448	        }
449	
450	      upper->status->head++;
451	    }
452	
453	  return ret;
454	}
