481	       caps->ac_type != AUDIO_TYPE_OUTPUT))
482	    {
483	#ifdef CONFIG_AUDIO_MULTI_SESSION
484	      ret = lower->ops->configure(lower, cap_desc->session, caps);
485	#else
486	      ret = lower->ops->configure(lower, caps);
487	#endif
488	      if (ret < 0 || (caps->ac_type != AUDIO_TYPE_INPUT &&
489	                      caps->ac_type != AUDIO_TYPE_OUTPUT))
490	        {
491	          return ret;
492	        }
493	
494	      /* INPUT/OUTPUT configure success here */
495	
496	      audio_setstate(upper, AUDIO_STATE_PREPARED);
