170	
171	  priv = kmm_zalloc(sizeof(*priv));
172	  if (priv == NULL)
173	    {
174	      return -ENOMEM;
175	    }
176	
177	  /* Get exclusive access to the device structures */
178	
179	  ret = nxmutex_lock(&upper->lock);
180	  if (ret < 0)
181	    {
182	      return ret;
183	    }
184	
185	  /* First open, alloc status memory */
186	
187	  if (upper->head == NULL)
188	    {
189	      upper->status = kumm_zalloc(sizeof(struct audio_status_s));
190	      if (!upper->status)
191	        {
192	          auderr("ERROR: Allocation status failed\n");
193	          ret = -ENOMEM;
194	          goto errout;
195	        }
196	    }
197	
198	  flags = spin_lock_irqsave(&upper->spinlock);
199	  priv->flink = upper->head;
200	  filep->f_priv = priv;
201	  upper->head = priv;
202	  spin_unlock_irqrestore(&upper->spinlock, flags);
203	  ret = OK;
204	
205	errout:
206	  nxmutex_unlock(&upper->lock);
207	  if (ret < 0)
208	    {
209	      kumm_free(priv);
210	    }
211	
212	  return ret;
