658	static int nxplayer_filltone(FAR struct nxplayer_tone_s *tone,
659	                             FAR struct ap_buffer_s *apb)
660	{
661	  FAR uint16_t *samples;
662	  float value;
663	  size_t i;
664	
665	  apb->nbytes = 0;
666	  apb->curbyte = 0;
667	  samples = (FAR uint16_t *)apb->samp;
