669	  if (tone->cur_samps >= tone->total_samps)
670	    {
671	      return -ENODATA;
672	    }
673	
674	  for (i = 0; i < apb->nmaxbytes / 4; i++)
675	    {
676	      value = sinf(2 * M_PI * tone->pitch_freq *
677	                   tone->cur_samps / tone->sample_rate);
678	      samples[i * 2 + 1] = samples[i * 2] = (uint16_t)(value * 10000);
679	
680	      tone->cur_samps++;
681	      apb->nbytes += 4;
682	
683	      if (tone->cur_samps >= tone->total_samps)
684	        {
685	          apb->flags |= AUDIO_APB_FINAL;
686	          break;
687	        }
688	    }
689	
690	  return 0;
