{
  FAR void *value;
  int id = 0;

  if (gettid() == pplayer->play_id)
    {
      return;
    }

  pthread_mutex_lock(&pplayer->mutex);

  if (pplayer->play_id > 0)
    {
      id = pplayer->play_id;
      pplayer->play_id = 0;
    }

  pthread_mutex_unlock(&pplayer->mutex);

  if (id > 0)
