static void nxplayer_refput(FAR struct nxplayer_s *pplayer)
{
  int refcount;

  pthread_mutex_lock(&pplayer->mutex);
  refcount = pplayer->crefs--;
  pthread_mutex_unlock(&pplayer->mutex);

  if (refcount == 1)
    {
      pthread_cond_destroy(&pplayer->cond);
      pthread_mutex_destroy(&pplayer->mutex);
      free(pplayer);
    }
}

static int nxplayer_jointhread(FAR struct nxplayer_s *pplayer)
{
  FAR void *value;
  pthread_t id;
  int result;
  int ret;

  pthread_mutex_lock(&pplayer->mutex);
  while (pplayer->join_in_progress)
    {
      pthread_cond_wait(&pplayer->cond, &pplayer->mutex);
    }

  id = pplayer->play_id;
  if (id <= 0)
    {
      result = pplayer->result;
      pthread_mutex_unlock(&pplayer->mutex);
      return result;
    }

  if (gettid() == id)
    {
      pthread_mutex_unlock(&pplayer->mutex);
      return -EDEADLK;
    }

  pplayer->join_in_progress = true;
  pthread_mutex_unlock(&pplayer->mutex);

  ret = pthread_join(id, &value);

  pthread_mutex_lock(&pplayer->mutex);
  if (ret == OK && pplayer->play_id == id)
    {
      pplayer->play_id = 0;
    }

  pplayer->join_in_progress = false;
  result = ret == OK ? pplayer->result : -ret;
  pthread_cond_broadcast(&pplayer->cond);
  pthread_mutex_unlock(&pplayer->mutex);
  return result;
}

