int nxplayer_stop(FAR struct nxplayer_s *pplayer)
{
  struct audio_msg_s term_msg;
  struct timespec deadline;
  mqd_t mq;
  bool notify;
  int ret;

  DEBUGASSERT(pplayer != NULL);

  /* Publish the predicate while synchronized, but never perform a possibly
   * blocking queue send while holding the lifecycle mutex.
   */

  pthread_mutex_lock(&pplayer->mutex);
  notify = pplayer->state != NXPLAYER_STATE_IDLE && !pplayer->thread_exited;
  mq = pplayer->mq;
  if (notify)
    {
      pplayer->stop_requested = true;
      pplayer->state = NXPLAYER_STATE_STOPPING;
      pplayer->result = -EINPROGRESS;
    }

  pthread_mutex_unlock(&pplayer->mutex);

  if (notify)
    {
      term_msg.msg_id = AUDIO_MSG_STOP;
      term_msg.u.data = 0;
      clock_gettime(CLOCK_REALTIME, &deadline);
      deadline.tv_sec++;
      ret = mq_timedsend(mq, (FAR const char *)&term_msg, sizeof(term_msg),
                         CONFIG_NXPLAYER_MSG_PRIO, &deadline);
      if (ret < 0 && errno != EBADF)
        {
          auderr("ERROR: Failed to send stop message: %d\n", errno);
        }
    }

  ret = nxplayer_wait(pplayer);
  return ret == -ECANCELED ? OK : ret;
}

