{
  if (pplayer == NULL || status == NULL)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&pplayer->mutex);
  status->state = pplayer->state;
  status->result = pplayer->result;
  pthread_mutex_unlock(&pplayer->mutex);
  return OK;
}

int nxplayer_wait(FAR struct nxplayer_s *pplayer)
{
  if (pplayer == NULL)
    {
      return -EINVAL;
    }

  return nxplayer_jointhread(pplayer);
}

