void nxplayer_release(FAR struct nxplayer_s *pplayer)
{
  /* External owners wait for the playthread before dropping their reference.
   * The playthread itself uses nxplayer_refput() and never joins itself.
   */

  nxplayer_jointhread(pplayer);
  nxplayer_refput(pplayer);
}

