846	static void sunxi_codec_set_spk(struct snd_codec *codec, int enable)
847	{
848		struct sunxi_codec_info *sunxi_codec = codec->private_data;
849		struct sunxi_codec_param *param = &sunxi_codec->param;
850		gpio_direction_t direction = GPIO_DIRECTION_INPUT;
851		gpio_data_t data = GPIO_DATA_LOW;
852		gpio_data_t target = enable ? param->pa_level : !param->pa_level;
853		int direction_ret;
854		int data_ret;
855		int direction_get_ret;
856		int data_get_ret;
857	
858		direction_ret = hal_gpio_set_direction(param->gpio_spk,
859							 GPIO_MUXSEL_OUT);
860		data_ret = hal_gpio_set_data(param->gpio_spk, target);
861		direction_get_ret = hal_gpio_get_direction(param->gpio_spk, &direction);
862		data_get_ret = hal_gpio_get_data(param->gpio_spk, &data);
863	
864		syslog(LOG_INFO,
865			"codec amp enable=%d gpio=%d target=%d dir=%d data=%d "
866			"ret=%d/%d/%d/%d\n",
867			enable, param->gpio_spk, target, direction, data,
868			direction_ret, data_ret, direction_get_ret, data_get_ret);
869	
870		if (enable)
871			hal_msleep(param->pa_msleep_time);
872	}
