874	static void sunxi_codec_playback_hp_route(struct snd_codec *codec, int spk, int onoff)
875	{
876		struct sunxi_codec_info *sunxi_codec = codec->private_data;
877	
878		if (onoff) {
879			if (sunxi_codec->chip_ver == CHIP_VER_A) {
880				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
881						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN),
882						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN));
883				/* ramp out enable */
884				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
885						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH),
886						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH));
887				/* digital DAC enable */
888				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
889						(0x1<<EN_DAC), (0x1<<EN_DAC));
890				hal_msleep(5);
891				/* analog DAC enable and unmute */
892				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
893						(0x1<<DACLEN) | (0x1<<DACREN) |
894						(0x1<<DACLMUTE) | (0x1<<DACRMUTE),
895						(0x1<<DACLEN) | (0x1<<DACREN) |
896						(0x1<<DACLMUTE) | (0x1<<DACRMUTE));
897				/* HEADPONEOUT */
898				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
899					(0x1<<HP_DRVEN) | (0x1<<HP_DRVOUTEN),
900					(0x1<<HP_DRVEN) | (0x1<<HP_DRVOUTEN));
901				/* Playback on */
902				snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL,
903					(0x1<<HPLDO_EN), (0x1<<HPLDO_EN));
904			} else {
905				/* digital DAC enable */
906				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
907						(0x1<<EN_DAC), (0x1<<EN_DAC));
908				snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
909						(0x1<<RDEN), (0x1<<RDEN));
910			}
911			if (spk)
912				sunxi_codec_set_spk(codec, 1);
913			sunxi_codec_playback_diag(codec, "hp-on");
914		} else {
915			if (spk)
916				sunxi_codec_set_spk(codec, 0);
917			/* Playback off */
918			if (sunxi_codec->chip_ver == CHIP_VER_A) {
919				/* HEADPONE_EN */
920				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
921						(0x1<<HP_DRVEN), (0x0<<HP_DRVEN));
922				/* power off */
923				/* note: HPLDO is always open to avoid KEY_ADC sampling fail */
924				/* snd_codec_update_bits(codec, SUNXI_POWER_ANA_CTL, */
925				/* 		(0x1<<HPLDO_EN), (0x0<<HPLDO_EN)); */
926				hal_msleep(30);
927				/* HEADPONE_OUT */
928				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
929						(0x1<<HP_DRVOUTEN), (0x0<<HP_DRVOUTEN));
930				/* analog DAC */
931				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
932						(0x1<<DACLEN) | (0x1<<DACREN),
933						(0x0<<DACLEN) | (0x0<<DACREN));
934				/* digital DAC */
935				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
936						(0x1<<EN_DAC), (0x0<<EN_DAC));
937	
938				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
939						(0x1<<RAMP_OUT_EN) | (0x1<<RSWITCH),
940						(0x0<<RAMP_OUT_EN) | (0x0<<RSWITCH));
941	
942				snd_codec_update_bits(codec, SUNXI_HP_ANA_CTL,
943						(0x1<<HPFB_BUF_EN) | (0x1<<HPFB_IN_EN),
944						(0x0<<HPFB_BUF_EN) | (0x0<<HPFB_IN_EN));
945			} else {
946				/* analog DAC */
947				snd_codec_update_bits(codec, SUNXI_DAC_ANA_CTL,
948						(0x1<<DACLEN) | (0x1<<DACREN),
949						(0x0<<DACLEN) | (0x0<<DACREN));
950				/* digital DAC enable */
951				snd_codec_update_bits(codec, SUNXI_DAC_DPC,
952						(0x1<<EN_DAC), (0x0<<EN_DAC));
953				snd_codec_update_bits(codec, SUNXI_RAMP_ANA_CTL,
954						(0x1<<RDEN), (0x0<<RDEN));
955			}
956			sunxi_codec_playback_diag(codec, "hp-off");
957		}
958	}
