1021	static int sunxi_codec_dapm_control(struct snd_pcm_substream *substream,
1022					struct snd_dai *dai, int onoff)
1023	{
1024		struct snd_codec *codec = dai->component;
1025		struct sunxi_codec_info *sunxi_codec = codec->private_data;
1026		struct sunxi_codec_param *param = &sunxi_codec->param;
1027	
1028		if (substream->dapm_state == onoff)
1029			return 0;
1030		if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
1031			/*
1032			 * Playback:
1033			 * Playback --> DAC --> DAC_DIFFER --> LINEOUT/HPOUT + (External Speaker)
1034			 */
1035	
1036			switch (param->pb_audio_route) {
1037			case PB_AUDIO_ROUTE_LINEOUT_SPK:
1038				sunxi_codec_playback_lineout_route(codec, 1, onoff);
1039				break;
1040			case PB_AUDIO_ROUTE_HEADPHONE_SPK:
1041				sunxi_codec_playback_hp_route(codec, 1, onoff);
1042				break;
1043			case PB_AUDIO_ROUTE_LINEOUT:
1044				sunxi_codec_playback_lineout_route(codec, 0, onoff);
1045				break;
1046			case PB_AUDIO_ROUTE_HEADPHONE:
1047				sunxi_codec_playback_hp_route(codec, 0, onoff);
1048				break;
1049			case PB_AUDIO_ROUTE_LO_HP:
1050				sunxi_codec_playback_lineout_route(codec, 0, onoff);
1051				sunxi_codec_playback_hp_route(codec, 0, onoff);
1052				break;
1053			case PB_AUDIO_ROUTE_LO_HP_SPK:
1054				sunxi_codec_playback_lineout_route(codec, onoff ? 0 : 1, onoff);
1055				sunxi_codec_playback_hp_route(codec, onoff ? 1 : 0, onoff);
1056				break;
1057			}
1058		} else {
1059			/*
1060			 * Capture:
1061			 * Capture1 <-- ADC1 <-- Input Mixer <-- LINEINL PGA <-- LINEINL
1062			 * Capture1 <-- ADC1 <-- Input Mixer <-- FMINL PGA <-- FMINL
1063			 *
1064			 * Capture2 <-- ADC2 <-- Input Mixer <-- LINEINR PGA <-- LINEINR
1065			 * Capture2 <-- ADC2 <-- Input Mixer <-- FMINR PGA <-- FMINR
1066			 *
1067			 * Capture3 <-- ADC3 <-- Input Mixer <-- MIC3 PGA <-- MIC3
1068			 */
1069			unsigned int channels = 0;
1070			channels = substream->runtime->channels;
1071	
1072			snd_print("channels = %u\n", channels);
1073			snd_print("adc flag:%d,%d,%d\n",
1074				param->adc1_flag, param->adc2_flag, param->adc3_flag);
